\subsection{Spatial Storyboard Planning and Generation}
\label{sec:region-based-generation}
% \label{sec:spg}

% \textbf{Region-based Storyboard planning and generation.}
\textbf{Spatial storyboard planning.} Given an input prompt $\mathcal{P}$ and number of desired storyboard frames $N$, we first leverage multi-modal chain-of-thought reasoning and planning \citep{zhang2023multimodal} in order to generate 
% a textual-storyboard consisting of 
detailed textual description $\{\mathcal{T}_1, \mathcal{T}_2, \dots \mathcal{T}_B\}$ and character placements / layout $\{\mathcal{L}_1, \mathcal{L}_2, \dots \mathcal{L}_B\}$ for each storyboard image $\{\mathcal{I}_1, \mathcal{I}_2, \dots \mathcal{I}_B\}$. In particular, given an input prompt $\mathcal{P}$ and large-language-model $\mathcal{M}$, the storyboard-reasoning and planning is performed as follows,
\begin{align}
   \mathbf{x} =  \{ (\mathcal{L}_i,  \mathcal{T}_i) \}_{i=1}^{N} = \mathcal{M}(\mathbf{x} \mid \mathcal{P}, B, D_{exemplar},\mathcal{C}),
   \label{eq:layout-pred}
\end{align}
where $\mathbf{x}$ is the model input,  $D_{exemplar}$ is the in-context learning dataset consisting of 4-5 human generated examples for prompt decomposition, and $\mathcal{C}$ is the chain-of-thought reasoning based task description. 
% Fig.~\ref{fig:method-overview} provides an overview of the generated outputs.
The output layout $\mathcal{L}_i$ for each storyboard-frame is predicted to contain tuples $\mathcal{L}_i = \{(\tau^k_i, m^k_i) \}_{k=1}^K$,  where $(\tau^k_i, m^k_i)$ represents the local object prompt and bounding-box mask respectively for the $k^{th}$ character and the $i^{th}$ storyboard frame. 
Fig.~\ref{fig:method-overview} provides an overview 
of the generated outputs. 
Please refer supplementary material for further implementation details.
% on exemplar-dataset and task-description.


\textbf{Region-based generation.} 
% We next adopt 
To constrain each output image to follow the predicted region-based constraints (refer Eq.~\ref{eq:layout-pred}), we next adopt 
 region-based generation approach from \citep{yang2024mastering}.
% a cross-attention (CA) masking approach. 
In particular, instead of computing the reverse diffusion hidden states as $\mathbf{z}^k_{t-1} = \mathcal{U}_{\theta}(z_t, t, \mathcal{T}_k )$ we use,
\begin{align}
    \mathbf{z}^k_{t-1} = f_{\text{RPG}} (z^k_t, t, \theta, \mathcal{T}_k, \mathcal{L}_k ),
\end{align}
where $f_{\text{RPG}}$ is the region-based sampling function from \citep{yang2024mastering}, $\theta$ refers to the weights of  diffusion model, $t$ is the timestep, and $(\mathcal{T}_k, \mathcal{L}_k)$ represent  global-prompt and character-layout respectively for storyboard frame $\mathcal{I}_k$. 
% Fig.~\ref{fig:method-overview} provides an overview of cross-attention masking for storyboard generation.
Please refer supplementary material for further details.


\subsection{Reducing Inter-character Self-Attention Leakage}
\label{sec:intercharacter-leakage}

