    \centering
    \begin{subfigure}{\columnwidth}
        \centering
        \includegraphics[width=\textwidth]{figure04a.pdf}
    \end{subfigure}
    \begin{subfigure}{\columnwidth}
        \centering
        \includegraphics[width=\textwidth]{figure04b.pdf}
    \end{subfigure}
\caption{Approximate error bounds for POD and QM Kernel ROMs for the advection-diffusion problem \cref{eq:advection_diffusion_pde}.}
    \label{fig:adv_diff_error_bound}
\end{figure}

Next, we compute the error bound from \Cref{thm:a_posteriori_error} for the feature map Kernel ROMs for $r\in\{6, 12\}$.
Although the computed Kernel ROMs use a nonzero regularization $\gamma\neq 0$, the computed error bounds still hold.
We estimate the norm $\|\tbf+\bdelta\|_{\cH_K^r}$ with the norm of the interpolant $\|\hbf\|_{\cH_K^r}$, which can be computed quickly and explicitly using equation \cref{eq:kernel_norm}.
The local logarithmic Lipschitz constant $\Lambda_\bM[\bff](\bg(\hbq(s)))$ is estimated using the logarithmic norm
$\lambda_\bM(\bff(\hbq(s)))$, and the weighting matrix $\bM$ is taken to be $\frac{1}{r}\bI_{r}$.
We also examine feature map Kernel ROMs where the chosen feature map does not match the true projection-based ROM form, i.e. POD with a quadratic feature map and QM with a linear feature map.
The results are displayed in \Cref{fig:adv_diff_error_bound}, which shows that the computed error estimates indeed bound the true error without dramatically overestimating it.
In the POD cases with linear ROMs, the $\alpha_P$ term, which is related to the POD projection errors, is what dominates the error bound computation, while the $\alpha_K$ term, which corresponds to the pointwise kernel error bound from \Cref{cor:vector_power_function_bound}, is negligible.
For the QM Quadratic ROM with $r=6$, $\alpha_P$ again dominates the error bound and the $\alpha_K$ is negligible.
However, for the QM Quadratic ROM with $r=12$, the $\alpha_K$ term is much larger.
This may indicate that the chosen quadratic feature map may yield a non-optimal model form for the Kernel ROM.
Indeed, since POD with $r=12$ already yields small ROM errors, one may expect that a QM is unnecessary for $r=12$, and thus the quadratic term in the Kernel ROM may be extraneous.
To test this, we remove the quadratic term, which comes from the quadratic component of $\bg$, and compute the error bound for a linear QM Kernel ROM with $r=12$.
We observe that the $\alpha_K$ term is once again negligible in this case.
On the other hand, adding a quadratic term to the POD ROM with $r=12$ also substantially increases $\alpha_K$.
Therefore, we can infer that a larger $\alpha_K$ contribution may indicate that a non-optimal model form (i.e.,\ feature map) was used for the Kernel ROM.

\subsection{1D Burgers' equation}\label{sec:numerics_burgers}

\begin{figure}[t]
    \centering
    \includegraphics[width=\textwidth]{figure05.png}
    \caption{Solutions of the full-order Burgers' model \cref{eq:burgers_fom} with initial conditions \cref{eq:burgers_initial_condition} for various choices of $\bmu$.}
    \label{fig:burgers_fom_state}
\end{figure}

We now consider the 1D viscous Burgers' equation with homogeneous Dirichlet boundary conditions, which is nonlinear with respect to the state:
\begin{subequations}\label{eq:burgers_pde}
    \begin{align}
        \pdt q(x, t) - \nu \pdxx q(x, t) + q(x, t) \pdx q(x, t) = 0,
        &\qquad
        x \in (0, 1), \quad t \in (0, T), \\
        q(0, t) = 0, \quad q(1, t) = 0,
        &\qquad t \in (0, T), \\
        \label{eq:burgers_initial_condition}
        q(x, 0) = q_0(x;\bmu) \coloneqq e^{-(x - \mu_1)^{2}/\mu_2^{2}},
        &\qquad x \in (0, 1).
    \end{align}
\end{subequations}
Here, $\nu>0$ is the viscosity, which we set to $\nu = 10^{-2}$ for our experiments.
Solutions to this system are characterized by sharp gradients along an advection front.
Just as in the previous problem, we consider parameterized Gaussian initial conditions with center $\mu_1\in[0.25,0.35]$ and $\mu_2\in[0.05,0.15]$, set the final time to $T=1$, use $n_q = n_t = 256$ spatial degrees of freedom and temporal observations, and draw $M = 10$ latin hypercube samples of the parameters $\bmu = [~\mu_1~~\mu_2~]\trp$ to use for generating training data.
The spatial discretization uses uniform centered finite differences, yielding a quadratic FOM of the form
\begin{align}
    \label{eq:burgers_fom}
    \dt \bq(t)
    = \bA \bq(t) + \bH[\bq(t)\otimes\bq(t)],
    \qquad
    \bq(0) = \bq_0(\bmu),
\end{align}
where $\bq(t),\bq_0(\bmu)\in\real^{n_q}$, $\bA\in\real^{n_q\times n_q}$, and $\bH\in\real^{n_q\times n_q^2}$.
We again use a BDF time integrator to solve the FOM (and constructed ROMs) at the parameter samples, resulting in $M = 10$ trajectories of $n_t + 1 = 257$ snapshots each.
The FOM states for a few parameter values are displayed in \Cref{fig:burgers_fom_state}.

\begin{table}[t]
\centering
\begin{tabular}{c|c}
    POD & $\bphi(\hbq) = \begin{bmatrix}
        1 \\ \hbq \\ \hbq \otimes \hbq
    \end{bmatrix},
    \qquad
    \bG = \frac{1}{1+r+r^2}
    \bI_{1+r+r^2}
$
    \\[.65cm] \hline \\[-.25cm]
    QM & $\bphi(\hbq) = \begin{bmatrix}
        1 \\ \hbq \\ \hbq \otimes \hbq \\ \hbq \otimes \hbq \otimes \hbq \\ \hbq \otimes \hbq \otimes \hbq \otimes \hbq
    \end{bmatrix},
    \qquad
    \bG = \begin{bmatrix}
            \bI_{1+r+r^2} &\bzero &\bzero \\
            \bzero & \norm{\bW}_F \bI_{r^3} &\bzero \\
            \bzero & \bzero & \norm{\bW}_F^2 \bI_{r^4} \\
\end{bmatrix}
    $
\end{tabular}
\caption{Feature maps and weighting matrices for POD and QM Kernel ROMs for the 1D Burgers' example.}
\label{tbl:burgers_kernel_table}
\end{table}

For both POD and QM, we use $\obq = \bf0$, hence the intrusive POD ROM takes the quadratic form \cref{eq:linear_qm_rom}, whereas the intrusive QM ROM has the quartic form \cref{eq:quadratic_qm_rom}.
For this problem, we apply the kernel input normalization discussed in \Cref{remark:kernel_normalization}, which is helpful for balancing the contribution of higher-order terms.
We therefore construct feature map Kernel ROMs to mirror the structure of the intrusive models, with the addition of a constant term that arises due to the input scaling (see \apdxref{appendix:fullquadstructure}), by using the feature maps and weighting matrices listed in \Cref{tbl:burgers_kernel_table}.
Similar to before, we learn Gaussian RBF Kernel ROMs with fixed shape parameter $\epsilon=10^{-1}$ and hybrid Kernel ROMs using the POD feature map from \Cref{tbl:burgers_kernel_table} with weighting coefficient $c_\phi=1$ and a Gaussian RBF kernel with $\epsilon=0.1$ and weighting coefficient $c_\psi=10^{-3}$, which result in ROMs of the form
\begin{align}\label{eq:burgers_hybrid_rhs}
    \dt\hbq(t)
= \hbc + \hbA\hbq(t) + \tbH [\tbq(t) \otimes \tbq(t)]
    + 10^{-3}\bOmega\trp\bpsi_{\!\epsilon}(\tbq(t)).
\end{align}
We also learn OpInf ROMs with the intrusive ROM structure, with the regularization designed so
\begin{align}
    \big\|\bGamma\hbO\trp\big\|_F^2
    = \gamma_1^2\|\hbA\|_{F}^{2} + \gamma_2^2\|\hbH\|_{F}^{2}
\end{align}
for the POD OpInf ROM, and
\begin{align}
    \big\|\bGamma\hbO\trp\big\|_F^2
    = \gamma_3^2(\|\hbH_{2}\|_{F}^{2} + \|\hbH_{3}\|_{F}^{2}) + \gamma_4^2\|\hbH_{4}\|_{F}^{2}
\end{align}
for the QM OpInf ROM, performing a grid search for $\gamma_1,\ldots,\gamma_4>0$.
The relative $L^\infty$-$L^2$ error \cref{eq:relative_linf_l2_error} is used to evaluate ROM performance at the testing parameter value $\bar{\bmu} = (0.3, 0.1)$.

\begin{figure}[t]
    \centering
    \includegraphics[width=\textwidth]{figure06.pdf}
    \caption{Relative ROM error at the test parameter $\bar{\bmu} = (0.3,0.1)$ as a function of number of basis vectors in linear POD (left) and quadratic manifold (right) state approximations.
    }
    \label{fig:romsize_vs_error-burgers}
\end{figure}

\Cref{fig:romsize_vs_error-burgers} reports results for various reduced dimensions $r$. All POD ROM errors are nearly identical to the POD projection error.
For the QM ROMs, the OpInf and Kernel ROMs have very similar performance for $r \leq 14$.
The feature map Kernel ROM errors plateau for $r > 14$,
while the OpInf and RBF Kernel ROMs plateau for $16<r<18$ and increase slightly for $r=19, 20$.
Notably, the hybrid Kernel ROM continues to match the projection and intrusive ROM error as $r$ increases, indicating that the RBF term in \cref{eq:burgers_hybrid_rhs} acts as a more accurate closure term for the ROM dynamics at larger values of $r$ compared to the cubic and quartic nonlinearities of the OpInf and FM Kernel ROMs.
Unlike the advection-diffusion case, the QM projection and intrusive ROM errors are notably lower than the corresponding POD errors, and thus QM dimension reduction may be beneficial for this problem.

