\section{Quadratic systems with QM approximations}
\label{appendix:fullquadstructure}

This appendix considers a linear-quadratic FOM,
\begin{align}
    \tag{\ref{eq:linearquadratic_fom}}
    \dt\bq(t)
    = \bff(\bq(t))
    \coloneqq \bA\bq(t) + \bH[\bq(t) \otimes \bq(t)],
\end{align}
and derives the structure of the corresponding intrusive projection-based ROM with a QM approximation,
\begin{align}
    \tag{\ref{eq:quadratic_decoder}}
    \bg(\tbq) = \obq + \bV\tbq + \bW[\tbq \otimes \tbq],
\end{align}
for nonzero $\obq\in\real^{n_q}$ and $\bW\in\real^{n_q\times r^2}$.
Specifically, we show that a nonzero reference vector $\obq$ causes a constant term to appear in the ROM dynamics.

Using the product rule $(\bX\otimes\bY)(\bZ\otimes\bU) = (\bX\bZ)\otimes(\bY\bU)$, we have
\begin{align*}
    \bg(\tbq) \otimes \bg(\tbq)
    &= \big(\obq + \bV\tbq + \bW[\tbq \otimes \tbq]\big) \otimes \big(\obq + \bV\tbq + \bW[\tbq \otimes \tbq]\big)
    \\
    &= \obq\otimes\obq + \obq\otimes(\bV\tbq) + \obq\otimes(\bW[\tbq \otimes \tbq])
    \\&\qquad
    + (\bV\tbq)\otimes\obq + (\bV\tbq)\otimes(\bV\tbq) + (\bV\tbq)\otimes(\bW[\tbq \otimes \tbq])
    \\&\qquad
    + (\bW[\tbq \otimes \tbq]) \otimes \obq + (\bW[\tbq \otimes \tbq]) \otimes (\bV\tbq) + (\bW[\tbq \otimes \tbq]) \otimes (\bW[\tbq \otimes \tbq])
    \\
    &= \obq\otimes\obq + (\obq\otimes\bV)\tbq + (\obq\otimes\bW)[\tbq \otimes \tbq]
    \\&\qquad
    + (\bV \otimes\obq)\tbq + (\bV \otimes \bV)[\tbq\otimes\tbq] + (\bV\otimes\bW)[\tbq \otimes \tbq \otimes \tbq]
    \\&\qquad
    + (\bW\otimes\obq)[\tbq \otimes \tbq] + (\bW\otimes \bV)[\tbq \otimes \tbq \otimes \tbq] + (\bW \otimes \bW)[\tbq \otimes \tbq \otimes \tbq \otimes \tbq]
    \\
    &= \obq\otimes\obq + (\obq\otimes\bV + \bV\otimes\obq)\tbq + (\obq\otimes\bW + \bV \otimes \bV + \bW\otimes\obq)[\tbq \otimes \tbq]
    \\&\qquad
    + (\bV\otimes\bW + \bW\otimes \bV)[\tbq \otimes \tbq \otimes \tbq]
    + (\bW \otimes \bW)[\tbq \otimes \tbq \otimes \tbq \otimes \tbq].
\end{align*}
Therefore,
\begin{align*}
    \bff(\bg(\tbq))
    &= \bA\big(\obq + \bV\tbq + \bW[\tbq \otimes \tbq]\big)
    + \bH[\bg(\tbq) \otimes \bg(\tbq)]
    \\
    &= \bA\obq + \bH[\obq\otimes\obq] + \big(\bA\bV + \bH(\obq\otimes\bV + \bV\otimes\obq)\big)\tbq
    \\&\qquad
    + \big(\bA\bW + \bH(\obq\otimes\bW + \bV \otimes \bV + \bW\otimes\obq)\big)[\tbq \otimes \tbq]
    \\&\qquad
    + \bH(\bV\otimes\bW + \bW\otimes \bV)[\tbq \otimes \tbq \otimes \tbq]
    + \bH(\bW \otimes \bW)[\tbq \otimes \tbq \otimes \tbq \otimes \tbq],
\end{align*}
so that the intrusive projection-based ROM \cref{eq:generic_rom-withgandh} can be written as
\begin{subequations}\label{eq:intrusive-quartic-apdx}
\begin{align}
    \begin{aligned}
    \dt\tbq(t)
    &= \bV\trp\bff(\bg(\tbq(t)))
    \\
    &= \tbc + \tbA \tbq(t) + \tbH_2 [\tbq(t) \otimes \tbq(t)]
    + \tbH_{3}[\tbq(t)\otimes\tbq(t)\otimes\tbq(t)]
    + \tbH_{4}[\tbq(t)\otimes\tbq(t)\otimes\tbq(t)\otimes\tbq(t)],
    \end{aligned}
\end{align}
where
\begin{align}
    \begin{aligned}
    \tbc &= \bV\trp(\bA\obq + \bH[\obq\otimes\obq]) \in \real^{r},
    \\
    \tbA &= \bV\trp\bA\bV + \bV\trp\bH(\obq\otimes\bV + \bV\otimes\obq) \in \real^{r\times r},
    \\
    \tbH_{2} &= \bV\trp\bA\bW + \bV\trp\bH(\obq\otimes\bW + \bV \otimes \bV + \bW\otimes\obq)\in\real^{r\times r^2},
    \\
    \tbH_{3} &= \bV\trp\bH(\bV\otimes\bW + \bW\otimes \bV)\in\real^{r\times r^{3}},
    \\
    \tbH_{4} &= \bV\trp\bH(\bW \otimes \bW) \in\real^{r\times r^4}.
    \end{aligned}
\end{align}
\end{subequations}

The quartic polynomial structure of \cref{eq:intrusive-quartic-apdx} also arises when $\obq = \bf0$ but a Kernel ROM is constructed with the input scaling preprocessing step of \Cref{remark:kernel_normalization}.
In that case, the matrices in \cref{eq:intrusive-quartic-apdx} reduce to
\begin{align*}
\tbA &= \bV\trp\bA\bV,
    &
    \tbH_{2} &= \bV\trp\bA\bW + \bV\trp\bH(\bV \otimes \bV),
    \\
    \tbH_{3} &= \bV\trp\bH(\bV\otimes\bW + \bW\otimes \bV),
    &
    \tbH_{4} &= \bV\trp\bH(\bW \otimes \bW),
\end{align*}
with $\tbc = \bf0$.
However, the Kernel ROM targets a shifted and scaled reduced state $\hbq(t) = \bSigma^{-1}(\tbq(t) - \obx)$ for some $\bSigma\in\real^{r\times r}$ and $\obx\in\real^{r}$, which evolves according to
\begin{align*}
    \dt\hbq(t)
    &= \dt\left[\bSigma^{-1}\tbq(t) - \bSigma^{-1}\obx\right]
    \\
    &= \bSigma^{-1}\big(\tbA \tbq(t) + \tbH_2 [\tbq(t) \otimes \tbq(t)]
    + \tbH_{3}[\tbq(t)\otimes\tbq(t)\otimes\tbq(t)]
    + \tbH_{4}[\tbq(t)\otimes\tbq(t)\otimes\tbq(t)\otimes\tbq(t)]\big)
    \\
    &= \bSigma^{-1}\big(\tbA (\bSigma\hbq(t) + \obx) + \tbH_2 [(\bSigma\hbq(t) + \obx) \otimes (\bSigma\hbq(t) + \obx)]
    \\&\qquad\qquad
    + \tbH_{3}[(\bSigma\hbq(t) + \obx)\otimes(\bSigma\hbq(t) + \obx)\otimes(\bSigma\hbq(t) + \obx)]
    \\&\qquad\qquad
    + \tbH_{4}[(\bSigma\hbq(t) + \obx)\otimes(\bSigma\hbq(t) + \obx)\otimes(\bSigma\hbq(t) + \obx)\otimes(\bSigma\hbq(t) + \obx)]\big)
    \\
    &= \hbc + \hbA \hbq(t) + \hbH_2 [\hbq(t) \otimes \hbq(t)]
    + \hbH_{3}[\hbq(t)\otimes\hbq(t)\otimes\hbq(t)]
    + \hbH_{4}[\hbq(t)\otimes\hbq(t)\otimes\hbq(t)\otimes\hbq(t)],
\end{align*}
where
\begin{align*}
    \hbc
    &= \bSigma^{-1}\big(\tbA\obx
    + \tbH_2 [\obx \otimes \obx]
    + \tbH_{3}[\obx \otimes \obx \otimes \obx]
    + \tbH_{4}[\obx \otimes \obx \otimes \obx \otimes \obx]\big)
    \in\real^{r},
    \\
    \hbA
    &= \bSigma^{-1}\big(
        \tbA\bSigma
        + \tbH_2(\bSigma\otimes\obx + \obx\otimes\bSigma)
        + \tbH_3(
            \bSigma\otimes\obx\otimes\obx
            + \obx\otimes\bSigma\otimes\obx
            + \obx\otimes\obx\otimes\bSigma
        )
    \\&\qquad\qquad
    + \tbH_4(
        \bSigma\otimes\obx\otimes\obx\otimes\obx
        + \obx\otimes\bSigma\otimes\obx\otimes\obx
        + \obx\otimes\obx\otimes\bSigma\otimes\obx
        + \obx\otimes\obx\otimes\obx\otimes\bSigma
    )
    \big)\in\real^{r\times r},
    \\
    \hbH_{2}
    &= \bSigma^{-1}\big(
        \tbH_2(\bSigma \otimes \bSigma)
        + \tbH_3(
            \bSigma\otimes\bSigma\otimes\obx
            + \bSigma\otimes\obx\otimes\bSigma
            + \obx\otimes\bSigma\otimes\bSigma
        )
    \\&\qquad\qquad
    + \tbH_4(
        \bSigma\otimes\bSigma\otimes\obx\otimes\obx
        + \bSigma\otimes\obx\otimes\bSigma\otimes\obx
        + \bSigma\otimes\obx\otimes\obx\otimes\bSigma
        \\&\qquad\qquad\qquad
        + \obx\otimes\bSigma\otimes\bSigma\otimes\obx
        + \obx\otimes\bSigma\otimes\obx\otimes\bSigma
        + \obx\otimes\obx\otimes\bSigma\otimes\bSigma
    )
    \big)\in\real^{r\times r^2},
    \\
    \hbH_{3}
    &= \bSigma^{-1}\big(
        \tbH_{3}(\bSigma\otimes\bSigma\otimes\bSigma)
    \\&\qquad\qquad
        + \tbH_{4}(
            \bSigma\otimes\bSigma\otimes\bSigma\otimes\obx
            + \bSigma\otimes\bSigma\otimes\obx\otimes\bSigma
            + \bSigma\otimes\obx\otimes\bSigma\otimes\bSigma
            + \obx\otimes\bSigma\otimes\bSigma\otimes\bSigma
        )
    \big)\in\real^{r\times r^3},
    \\
    \hbH_{4} &= \bSigma^{-1}\tbH_{4}(\bSigma\otimes\bSigma\otimes\bSigma\otimes\bSigma)
    \in\real^{r\times r^{4}}.
\end{align*}
The salient point is that none of these matrices need to be constructed explicitly when using a non-intrusive model reduction method: only the desired structure is needed to design the non-intrusive ROM.

\section{Stability for linear systems}
\label{appendix:lti_stability_error}

The following stability result illustrates the importance of the regularization hyperparameter $\rho \ge 0$ when solving the minimization problem \cref{eq:qm_optimization_problem} for computing $\bW$.
Applying the QM approach with reference state $\obq=\bzero$ to a linear FOM
\begin{align}
    \dt\bq(t) = \bA\bq(t),
    \qquad
    \bq(0) = \bq_0(\bmu),
\end{align}
results in a ROM with quadratic dynamics
\begin{align}\label{eq:linear_qm_rom_appendix}
    \dt \tbq(t) = \tbA\tbq(t) + \tbH[\tbq(t)\otimes\tbq(t)],
    \qquad \tbq(0) &= \bV\trp\bq_0(\bmu),
\end{align}
where
$\tbA = \bV\trp \bA \bV$ and $\tbH = \bV\trp \bA \bW$.
We then have a stability estimate for the ROM solution

\begin{proposition}\label{thm:lti_stability}
Let $\lambda$ denote the maximum eigenvalue of $\bA_{sym}=\frac{1}{2}(\bA+\bA\trp)$ (the symmetric part of $\bA$).
Then the following stability estimate for the QM ROM \cref{eq:linear_qm_rom_appendix} holds for all $t\in [0, T]$:
    \begin{align}\label{eq:stablity_result}
        \norm{\tbq(t)}_2\leq \norm{\bA}_2\norm{\bW}_2\int_0^t \|\tbq(s)\otimes\tbq(s)\|_2 e^{\lambda(t-s)}ds + e^{\lambda t} \norm{\bV\trp\bq_0}_2.
    \end{align}
\end{proposition}
\begin{proof}
    Observe that
    \begin{align}
        \label{eq:lti_stability_bound1}
        \begin{aligned}
        \tbq(t)\trp\dt\tbq(t)
        &= \tbq(t)\trp \bV\trp\bA \bV \tbq(t) + \tbq(t)\trp\bV\trp\bA\bW [\tbq(t)\otimes\tbq(t)]\\
        &= \tbq(t)\trp \bV\trp\bA_{sym} \bV \tbq(t) + \tbq(t)\trp\bV\trp\bA\bW [\tbq(t)\otimes\tbq(t)]\\
        &\leq \lambda\norm{\bV\tbq(t)}_2^2 + \norm{\bA}_2\norm{\bW}_2\norm{\bV\tbq(t)}_2\|\tbq(t)\otimes\tbq(t)\|_2\\
        &= \lambda\norm{\tbq(t)}_2^2 + \norm{\bA}_2\norm{\bW}_2\norm{\tbq(t)}_2\|\tbq(t)\otimes\tbq(t)\|_2,
        \end{aligned}
    \end{align}
    where the last line follows from the orthonormality of $\bV$.
    The bound \cref{eq:lti_stability_bound1} implies that
    \begin{align*}
        \dt\norm{\tbq(t)}_2 =\frac{\tbq(t)\trp\dt\tbq(t)}{\norm{\tbq(t)}_2} \leq
        \lambda\norm{\tbq(t)}_2 + \norm{\bA}_2\norm{\bW}_2\|\tbq(t)\otimes\tbq(t)\|_2
    \end{align*}
    Applying \Cref{lem:gronwall} with $u(t)=\norm{\tbq(t)}_2$,
    $\alpha(t)=\norm{\bA}_2\norm{\bW}_2\|\tbq(t)\otimes\tbq(t)\|_2$,
    and $\beta(t)=\lambda$ yields the result.
\end{proof}

\Cref{thm:lti_stability} indicates that the magnitude of $\norm{\bW}_2$ has a crucial impact on the stability of the resulting QM ROM.
Consequently, it is important to apply sufficient regularization (i.e., choose $\rho$ large enough) when computing $\bW$ to ensure that $\norm{\bW}_2$ remains small.

