&
w_{100} \, \langle \boldsymbol{\tau}_1 , \mathbf{P}_{100} \rangle
&
w_{001} \, \langle \boldsymbol{\tau}_1 , \mathbf{P}_{001} \rangle
&
w_{101} \, \langle \boldsymbol{\tau}_1 , \mathbf{P}_{101} \rangle
\end{pmatrix} 
= 
1
\ ,\\[4pt] 
\label{matrix: syz u}
\rank
\begin{pmatrix}
