\end{pmatrix}
=
1
\ .
\end{gather}
To elaborate, we demonstrate the equivalence between the existence of a syzygy of degree $(0,1,0)$ and \cref{matrix: syz t}.
Redefine $\mbf{g}_j = \mbf{g}_j(s_0,s_1,u_0,u_1) = \sum_{0\leq i,j\leq 1} w_{ijk} \, \mbf{P}_{ijk} \, s_i u_k$, and let $\bs{\pi} = \bs{\pi}_0 \, t_0 + \bs{\pi}_1 \, t_1$ be a syzygy of $\mbf{f}$. 
Following the lines of the proof of \cref{lemma: linear syz s}, the scalar product $\langle 
\bs{\pi} 
, 
\mbf{f}
\rangle$ equals 
\begin{equation}
\label{syzygy betas}
t_0 
t_1 
( 
\langle 
\boldsymbol{\pi}_0 
, 
\mbf{g}_1
\rangle 
+ 
\langle 
\boldsymbol{\pi}_1 
, 
\mbf{g}_0
\rangle 
)
= 
t_0 t_1
\sum_{0\leq i,k\leq 1} 
\left(
\beta_0
w_{i1k}
\langle 
\bs{\pi}_0 , 
\mbf{P}_{i1k}
\rangle 
+  
\beta_1
w_{i0k}
\langle 
\bs{\pi}_1 , 
\mbf{P}_{i0k}
\rangle 
\right)
s_i u_k
= 0
\ ,
\end{equation}
since the vanishing $\langle \bs{\pi} , \mbf{f}\rangle = 0$ readily implies $\bs{\pi}_j = \beta_j \, \bs{\tau}_j$ for some nonzero $\beta_0,\beta_1$. 
In particular, such $(\beta_0,\beta_1)\in \C^2$ exists if and only if \cref{syzygy betas} holds.
\end{remark}


\section{Hexahedral birational maps}
\label{sec: hexahedral}

In this section, we study the first and simplest family of trilinear birational maps: the class of hexahedral birational maps.  

\begin{definition}
\label{def: hexahedral}
A trilinear rational map is hexahedral if all the boundary surfaces are planes.
\end{definition}

Hexahedral birational maps are the direct generalization to 3D of the 2D quadrilateral birational maps studied in \cite{sederberg2D,EFFECTIVE_BIGRAD}, since the minimal graded free resolution of their base ideal is Hilbert-Burch \cite[Proposition 6.2]{trilinear}. 

\subsection{Geometric constraints}
\label{geometric constraint: hexahedral}

We begin describing the geometric constraints on the control points that are necessary for birationality. 
The following observation is straightforward.

\begin{fact}
\label{fact: hexahedral}
If $\phi$ is birational of type $(1,1,1)$, then it is also hexahedral.  
\end{fact} 

\begin{proof}
If $\phi$ is birational of type $(1,1,1)$ the polynomials $A_i$, $B_j$, and $C_k$ in \cref{algebraic relations} are all linear. 
Since the relations in \cref{algebraic relations} define the equations of the parametric surfaces for each of the three parameters, it follows that, for any specialization of these, the corresponding surfaces satisfy a linear equation. 
Therefore, all the parametric surfaces are planes. 
Since the boundary surfaces are also parametric, $\phi$ is hexahedral.
\end{proof}

In practice, the control points of a hexahedral map can be given indirectly through the boundary planes $\Sigma_i$, $T_j$, $Y_k$. 
More explicitly, we have the following construction. 

\begin{construction} 
\label{construction: hexahedral}
The control points of a hexahedral rational map can be generated as follows: 
\vskip2pt
\begin{enumerate}
\item As input, for each $0\leq i,j,k \leq 1$ choose pairwise distinct planes $\Sigma_i$, $T_j$, $Y_k$, or equivalently, vectors $\bs{\sigma}_i$, $\bs{\tau}_j$, $\bs{\upsilon}_k$ in $\R^4$, whose intersection is an affine point. 
\item As output, compute $\mbf{P}_{ijk} = \Sigma_i \cap T_j \cap Y_k$ for each $0\leq i,j,k\leq 1$
\end{enumerate}  
\end{construction} 

\subsection{Birational weights and tensor rank criterion}
\label{tensor criterion: hexahedral}

\begin{notation}
\label{hexahedral: deltas}
If $\phi$ is hexahedral, according to \cref{{construction: hexahedral}} each control point $\mbf{P}_{ijk}$ can be expressed as the wedge of the vectors $\bs{\sigma}_i$, $\bs{\tau}_j$, and $\bs{\upsilon}_k$ defining the boundary planes. More specifically, we have 
$
\mbf{P}_{ijk} = \Delta_{ijk}^{-1} \ \bs{\sigma}_i \wedge \bs{\tau}_j \wedge \bs{\upsilon}_k 
$, 
where 
\begin{equation}
\label{eq: Deltas hexahedral}
\Delta_{ijk} = 
\begin{vmatrix}
\sigma_{1i} & \sigma_{2i} & \sigma_{3i} \\ 
\tau_{1j} & \tau_{2j} & \tau_{3j} \\ 
\upsilon_{1k} & \upsilon_{2k} & \upsilon_{3k} 
\end{vmatrix} 
\end{equation}
for each $0\leq i,j,k \leq 1$. 
In particular, $\Delta_{ijk} = 0$ if and only if $\mbf{P}_{ijk}$ lies at the plane $x_0 = 0$ in $\P^3$, a possibility is excluded since by definition $\mbf{P}_{ijk} = (1,x_{ijk},y_{ijk},z_{ijk})$. 
\end{notation}

The following theorem establishes our birationality criterion for the class of hexahedral rational maps, based on a rank-one condition on a $2\times 2\times 2$ tensor. 
It relates birationality, the existence of linear syzygies, and tensor rank. 
Moreover, it is the key ingredient for our constructive results. 
Recall that a tensor $T$ in $\C^{r_1}\otimes\ldots\otimes\C^{r_n}$ has \textit{rank one} if $T = \bs{\alpha}_1\otimes \ldots \otimes \bs{\alpha}_n$ for some $\bs{\alpha}_i \in \C^{r_i}$. 
For a global perspective about tensor rank, we  refer the reader to  \cite{tensorbook,ottaviani_tensor_rank,CPD_2}. 

\begin{theorem}
\label{theorem: tensor hexahedral}
Let $\phi$ be hexahedral. 
Then, $\phi$ is birational of type $(1,1,1)$ if and only if the $2\times 2\times 2$ tensor 
\begin{equation}
W
=
%\label{chapter: constructive - eq: tensor birational (1,1,1)}
\left( 
\frac{w_{ijk}}{\Delta_{ijk}}
\right)_{0\leq i,j,k \leq 1}
\end{equation} 
has rank one. 
\end{theorem} 

\begin{proof} 
By \cite[Theorem $6.1$]{trilinear}, it follows that $\phi$ is birational of type $(1,1,1)$ if and only if $\mathbf{f}$ admits syzygies of degrees $(1,0,0)$, $(0,1,0)$, and $(0,0,1)$. 
Equivalently, by \cref{lemma: linear syz s} and \cref{linear syz t u}, $\phi$ is birational if and only if the matrix rank conditions \cref{matrix: syz s}, \cref{matrix: syz t}, and \cref{matrix: syz u} are simultaneously satisfied. 
We now rewrite these rank conditions so that the matrices involved have the same entries. 
Namely, for any $0\leq i,j,k \leq 1$ we can write  
\begin{equation} 
\Delta_{0jk} 
\, 
\langle \boldsymbol{\sigma}_1 , \mathbf{P}_{0jk} \rangle
=
\boldsymbol{\sigma}_1
\wedge
\boldsymbol{\sigma}_{0}
\wedge
\boldsymbol{\tau}_{j}
\wedge
\boldsymbol{\upsilon}_{k}
= 
- 
\Delta_{1jk}
\,
\Delta_{1jk}^{-1}
\,
\boldsymbol{\sigma}_0
\wedge
\boldsymbol{\sigma}_1
\wedge
\boldsymbol{\tau}_j
\wedge
\boldsymbol{\upsilon}_k 
= 
- 
\Delta_{1jk} 
\, 
\langle 
\boldsymbol{\sigma}_0 
, 
\mathbf{P}_{1jk}
\rangle 
\ .
\end{equation}
Hence, we have 
$$
\begin{vmatrix}
\langle \bs{\sigma}_0 , \mbf{P}_{1jk} \rangle & - \langle \bs{\sigma}_1 , \mbf{P}_{0jk} \rangle\\
\Delta_{0jk} & \Delta_{1jk}
\end{vmatrix} 
= 0
\ ,
$$
and \cref{matrix: syz s} can be equivalently written as
\begin{equation}
\rank
\begin{pmatrix}
w_{100} \, {\Delta_{100}}^{-1}
&
w_{110} \, {\Delta_{110}}^{-1}
&
w_{101} \, {\Delta_{101}}^{-1}
&
w_{111} \, {\Delta_{111}}^{-1}
\\
w_{000} \, {\Delta_{000}}^{-1}
&
w_{010} \, {\Delta_{010}}^{-1}
&
w_{001} \, {\Delta_{001}}^{-1}
&
w_{011} \, {\Delta_{011}}^{-1}
\end{pmatrix}
=
1
\ .
\end{equation} 
With a similar argument, we derive 
$$
\Delta_{i0k} 
\, 
\langle 
\boldsymbol{\tau}_1 
, 
\mathbf{P}_{i0k}
\rangle 
= 
- 
\Delta_{i1k} 
\, 
\langle 
\boldsymbol{\tau}_0 
, 
\mathbf{P}_{i1k}
\rangle 
\ \ ,\ \ 
\Delta_{ij0} 
\, 
\langle 
\boldsymbol{\upsilon}_1 
, 
\mathbf{P}_{ij0}
\rangle 
= 
- 
\Delta_{ij1} 
\, 
\langle 
\boldsymbol{\upsilon}_0 
, 
\mathbf{P}_{ij1}
\rangle 
\ ,
$$
and \cref{matrix: syz t}, \cref{matrix: syz u} can be respectively rewritten as 
\begin{gather}
%\label{chapter: constructive - eq: new rank condition t (1,1,1)}
\rank
\begin{pmatrix}
w_{010} \, {\Delta_{010}}^{-1}
&
w_{110} \, {\Delta_{110}}^{-1} 
&
w_{011} \, {\Delta_{011}}^{-1}
&
w_{111} \, {\Delta_{111}}^{-1}
\\
w_{000} \, {\Delta_{000}}^{-1}
&
w_{100} \, {\Delta_{100}}^{-1}
&
w_{001} \, {\Delta_{001}}^{-1} 
&
w_{101} \, {\Delta_{101}}^{-1} 
\end{pmatrix}
=
1
\ ,\\
%\label{chapter: constructive - eq: new rank condition u (1,1,1)}
\rank
\begin{pmatrix}
w_{001} \, {\Delta_{001}}^{-1} 
&
w_{101} \, {\Delta_{101}}^{-1}
&
w_{011} \, {\Delta_{011}}^{-1}
&
w_{111} \, {\Delta_{111}}^{-1}
\\
w_{000} \, {\Delta_{000}}^{-1}
&
w_{100} \, {\Delta_{100}}^{-1}
&
w_{010} \, {\Delta_{010}}^{-1}
&
w_{110} \, {\Delta_{110}}^{-1}
\end{pmatrix}
=
1
\ .
\end{gather} 
In particular, the matrices involved in the three rank conditions above are the three flattenings of the tensor $W$ in the statement (see  \cite{tensorbook,ottaviani_tensor_rank,CPD_2}). 
By \cite[Proposition $3.11$]{ottaviani_tensor_rank}, they have all rank one if and only if $W$ has rank one, and the statement follows.
\end{proof} 

\begin{corollary} 
\label{corollary: weight formulas hexahedral}
Let $\phi$ be hexahedral. Then, $\phi$ is birational of type $(1,1,1)$ if and only if 
\begin{equation}
\label{eq: weight formulas hexahedral}
w_{ijk} = \alpha_i \, \beta_j \, \gamma_k \, \Delta_{ijk}
\end{equation}
for some $(\alpha_0:\alpha_1)\times (\beta_0:\beta_1)\times (\gamma_0:\gamma_1)$ in $(\P_\R^1)^3$. 
\end{corollary}

The choice of weights presented in \cref{corollary: weight formulas hexahedral}, as well as those for subsequent classes discussed in the following sections, can be understood through the following geometric interpretation.
The inverse rational map for each parameter corresponds to the linear parametrization of the parametric surfaces, explicitly given by \cref{algebraic relations}, as detailed in \cref{trilinear birational}. 
These parametrizations are determined by the images of three distinct points: \((1:0)\) and \((0:1)\),  which by assumption always map to the boundary surfaces, and a third point determined by the weights. 
Ensuring the rank-one condition guarantees that the three pencils of surfaces satisfy the algebraic relations necessary for birationality. 
Specifically, the weights determine the base locus of \(\phi^{-1}\), and the related contractions and blow-ups.

\subsection{Inverse and base locus}
\label{inverse: hexahedral}

We now address the most relevant computational advantage of birational maps: the efficient and exact computation of preimages. 
The following result presents explicit formulas for the inverse of a hexahedral birational map. 
In the remainder of the paper, we say that $\phi$ \textit{contracts}, or \textit{blows down}, a variety $V \subset (\P^1)^3$ if $\dim V > \dim \phi(V)$.

\begin{theorem} 
\label{theorem: inverse hexahedral}
Let $\phi$ be hexahedral with weights as \cref{eq: weight formulas hexahedral}. 
Then, $\phi^{-1}$ is given by 
\begin{equation}
\label{eq: inverse formula hexahedral}
(x_0:x_1:x_2:x_3) \mapsto 
(
-\alpha_1 \, \sigma_1 : \alpha_0 \, \sigma_0
)
\times 
(
-\beta_1 \, \tau_1 : \beta_0 \, \tau_0
)
\times 
(
-\gamma_1 \, \upsilon_1 : \gamma_0 \, \upsilon_0
)
\ .
\end{equation}
Additionally, we have the following:
\vskip2pt 
\begin{enumerate}
\item The base locus of $\phi$ is the curve $C$ in $(\P^1)^3$ defined by the ideal  
\begin{gather*}
\label{eq: base ideal hexahedral}
\left(
\sum
_{
0\leq j,k\leq 1}
w_{0jk}
\langle 
\bs{\sigma}_{1}
,
\mbf{P}_{0jk}
\rangle
\, t_{j} u_{k}
\, ,\, 
\sum
_{
0\leq i,k\leq 1}
w_{i0k}
\langle 
\bs{\tau}_{1}
,
\mbf{P}_{i0k}
\rangle
\, s_{i} u_{k}
\, ,\, 
\sum
_{
0\leq i,j\leq 1}
w_{ij0}
\langle 
\bs{\upsilon}_{1}
,
\mbf{P}_{ij0}
\rangle
\, s_{i} t_{j}
\right)
\end{gather*}
\item The base locus of $\phi^{-1}$ is the union of the lines $s = \Sigma_0 \cap \Sigma_1$, $t = T_0 \cap T_1$, and $u = Y_0\cap Y_1$
\item $\phi$ contracts the surfaces in $\PPP$ defined by the first, second, and third generators of the ideal in $1$ respectively to the lines $s,t$, and $u$
\item If $s,t$, and $u$ are pairwise skew, $\phi$ blows up $C$ to the unique (smooth) quadric through them
\end{enumerate}
\end{theorem}

\begin{proof}
By \cref{corollary: weight formulas hexahedral}, a hexahedral rational map is birational if and only if the weights satisfy \cref{eq: weight formulas hexahedral} for some $(\alpha_0:\alpha_1)\times (\beta_0:\beta_1)\times (\gamma_0:\gamma_1)$ in $(\P_\R^1)^3$.  
In particular, we can write 
\begin{gather*}
\mbf{f} 
= 
\sum_{0\leq i,j,k \leq 1} 
w_{ijk} 
\, 
\mbf{P}_{ijk} 
\, 
s_i t_j u_k
= 
\sum_{0\leq i,j,k \leq 1} 
\left( 
\alpha_i
\, 
\beta_j
\, 
\gamma_k
\, 
\Delta_{ijk}
\right)
\, 
\left( 
\Delta_{ijk}^{-1}
\, 
\bs{\sigma}_i
\wedge
\bs{\tau}_j
\wedge 
\bs{\upsilon}_k
\right)
\, 
s_i t_j u_k 
= 
\\
\sum_{0 \leq i,j,k \leq 1} 
(\alpha_i \, \bs{\sigma}_i \, s_i)
\wedge
(\beta_i \, \bs{\tau}_j \, t_j)
\wedge 
(\gamma_k \, \bs{\upsilon}_k \,u_k) 
= 
\bs{\sigma}(s_0,s_1) 
\wedge 
\bs{\tau}(t_0,t_1) 
\wedge 
\bs{\upsilon}(u_0,u_1) 
\ ,
\end{gather*} 
where $\bs{\sigma}=\bs{\sigma}(s_0,s_1)$ is as in \cref{lemma: linear syz s} and $\bs{\tau}=\bs{\tau}(t_0,t_1)$, $\bs{\upsilon}=\bs{\upsilon}(u_0,u_1)$ are analogous. 
Therefore, we find the relations 
$$
\langle
\bs{\sigma} 
, 
\mbf{f} 
\rangle 
= 
\bs{\sigma} 
\wedge 
\bs{\sigma} 
\wedge 
\bs{\tau} 
\wedge
\bs{\upsilon} 
= 
0 
\ ,\
\langle
\bs{\tau} 
, 
\mbf{f} 
\rangle 
= 
\bs{\tau}
\wedge 
\bs{\sigma} 
\wedge 
\bs{\tau} 
\wedge
\bs{\upsilon} 
= 
0 
\ ,\ 
\langle
\bs{\upsilon} 
, 
\mbf{f} 
\rangle 
= 
\bs{\upsilon}
\wedge 
\bs{\sigma} 
\wedge 
\bs{\tau} 
\wedge
\bs{\upsilon} 
= 
0 
\ ,
$$
yielding independent linear syzygies. 
Therefore, $\phi^{-1}$ is given by \cref{eq: inverse formula hexahedral}. 

Now, we prove the remaining four claims. 
Let $i^*$ stand for the converse of a binary index, namely $0^* = 1$ and $1^* = 0$. 
%Additionally, let $I'$ be the ideal on the right-hand side of \cref{eq: base ideal hexahedral}. 
For each $i = 0,1$, we can write 
\begin{equation}
\label{eq: pullback of matrix syz}
\langle 
\boldsymbol{\sigma}_i 
, 
\mathbf{f} 
\rangle 
=
s_{i^*}
\sum_{0\leq j,k \leq 1}
w_{i^*jk} 
\, 
\langle 
\boldsymbol{\sigma}_i 
, 
\mathbf{P}_{i^*jk}
\rangle 
\, 
t_j
\, 
u_k 
= 
s_{i^*}
\, 
g_i(t_0,t_1,u_0,u_1)
\end{equation}
since by definition $\langle \boldsymbol{\sigma}_i , \mathbf{P}_{ijk}\rangle = 0$ for any $0\leq j,k\leq 1$.
The coefficients of $g_i$ (in the monomial basis) coincide with the entries of the $(i+1)$-th row of the matrix in \cref{matrix: syz s}. 
Since $\mbf{f}$ admits a syzygy of degree $(1,0,0)$, by \cref{lemma: linear syz s} the rank condition \cref{matrix: syz s} holds. 
%In particular, $g_0$ and $g_1$ are proportional to the first generator $g$ of $I'$. 
Hence, $g_0,g_1$ are proportional to some bilinear $g$ and 
$$
(
\langle \bs{\sigma}_0,\mbf{f}\rangle 
,
\langle \bs{\sigma}_1,\mbf{f}\rangle 
)
= 
(\sigma_0(f_0,f_1,f_2,f_3)
,
\sigma_1(f_0,f_1,f_2,f_3))
: \mathfrak{N}^\infty
= 
(g)
\ ,
$$
where $\mathfrak{N}=(s_0,s_1)\cap(t_0,t_1)\cap(u_0,u_1)$ is the irrelevant ideal in $R$. 
Geometrically, this means that $\phi$ contracts the surface in $(\P^1)^3$ defined by $g = 0$ to the line $s = \Sigma_0 \cap \Sigma_1$, defined by the ideal $(\sigma_0,\sigma_1)\subset \R[x_0,x_1,x_2,x_3]$. 
With parallel arguments, it follows that $\phi$ contracts the surfaces defined by the second and third generators of the ideal in $1$ to the lines $t$ and $u$, respectively.
By \cref{eq: pullback of matrix syz} and the analogous identities for the other two pairs of variables, this ideal is precisely the saturation of $B = (f_0,f_1,f_2,f_3)$ and defines the base locus of $\phi$. 
Furthermore, the base ideal (resp$.$ locus) of $\phi^{-1}$ is  
$
(\sigma_0,\sigma_1) \cap (\tau_0,\tau_1) \cap (\upsilon_0,\upsilon_1)
\subset \R[x_0,x_1,x_2,x_3]
$
(resp$.$ $s\cup t\cup u$ in $\P^3$). 
Finally, since the composition $\phi\circ \phi^{-1}:\P^3\dashrightarrow\P^3$ yields the identity in an open set, we find 
%on $\mbf{f} = (f_0,f_1,f_2,f_3)$ yield the vector of polynomials
$$ 
(
f_0(A_0,A_1,B_0,B_1,C_0,C_1)
\, ,\, 
\ldots 
\, ,\, 
f_3(A_0,A_1,B_0,B_1,C_0,C_1)
)
=
q\cdot 
(
x_0,x_1,x_2,x_3
)
$$ 
for some quadratic form $q = q(x_0,x_1,x_2,x_3)$ that vanishes at the three lines $s,t$, and $u$. 
If these are pairwise skew, then $q = 0$ is the unique quadric through the lines.
\end{proof}

\section{Pyramidal birational maps} 
\label{sec: pyramidal}

We now study the second family of birational maps: the class of pyramidal birational maps. 
This name is motivated by the geometry of the control points.

\begin{definition}
\label{def: pyramidal}
A trilinear rational map is pyramidal if for one of the three parameters:
\begin{enumerate}
\item The four boundary lines intersect at a point
\item The two boundary surfaces are quadrics
\end{enumerate} 
\end{definition}

\subsection{Geometric constraint}
\label{geometric constraint: pyramidal}

First, we prove that a general birational map of type either $(1,1,2)$, $(1,2,1)$, or $(2,1,1)$ is pyramidal.
Without loss of generality, we can restrict to $(1,1,2)$. 

\begin{proposition} 
\label{type pyramidal}
If $\phi$ is a general birational map of type $(1,1,2)$, then it is pyramidal. 
Moreover, 
$$
Y_0 \cap Y_1 = s \cup t \cup C
\ ,
$$ 
where $s = \Sigma_0 \cap \Sigma_1$, $t = T_0\cap T_1$, and $C$ is a plane conic that intersects both $s$ and $t$. 
\end{proposition} 

\begin{proof}
Since $\phi$ is general, \cref{property: nondegeneracy} is satisfied. 
Moreover, by \cite[Theorem $5.4$]{trilinear} we find 
\begin{equation} 
(f_0 , f_1 , f_2 , f_3)  : \mathfrak{N}^\infty = (a_0 , b_0 , c_0) \cap (h , c_1)
\end{equation}
for some linear $a_0 = a_0(s_0,s_1)$, $b_0 = b_0(t_0,t_1)$, $c_k = c_k(u_0,u_1)$ for $k = 0,1$, and bilinear irreducible $h = h(s_0,s_1,t_0,t_1)$, where $\mathfrak{N}\subset R$ is the irrelevant ideal.  
Let $\phi^{-1}$ be defined by 
$$
(x_0,x_1,x_2,x_3) \mapsto (A_0:A_1)\times (B_0:B_1)\times (C_0:C_1)
$$
for some linear $A_i = A_i(\mbf{x})$, $B_j = B_j(\mbf{x})$ and quadratic $C_k = C_k(\mbf{x})$. 
Since $\phi\circ\phi^{-1}:\P^3 \dashrightarrow \P^3$ yields the identity in an open set, we find 
$$
(f_0(A_0,A_1,B_0,B_1,C_0,C_1) \, , \, \ldots \, , \, f_3(A_0,A_1,B_0,B_1,C_0,C_1)) 
= 
F\cdot 
(x_0,x_1,x_2,x_3)
$$ 
for some cubic form $F = F(\mbf{x})$. 
Therefore, the pullback ideals 
$$
(a_0(A_0,A_1),b_0(B_0,B_1),c_0(C_0,C_1)) 
\ ,\ 
(h(A_0,A_1,B_0,B_1),c_1(C_0,C_1))
$$ 
%defined by the specializations $s_i\mapsto A_i$, $t_j \mapsto B_j$, $u_k \mapsto C_k$ for each $0\leq i,j,k\leq 1$, 
are principal in $\R[x_0,x_1,x_2,x_3]$, and respectively generated by a linear and a quadratic form. 
In particular, the linear polynomials $a_0(A_0,A_1)$ and $b_0(B_0,B_1)$ are proportional, and define a plane $\Pi_0$. 
Geometrically, this means that the boundary planes $\Sigma_0,\Sigma_1, T_0$, and $T_1$ are not independent, and they intersect at a point $\mbf{A}$ in $\P_\R^3$. Hence, the four boundary $u$-lines, i$.$e$.$ $u_{ij} = \Sigma_i \cap T_j$ for each $0\leq i,j\leq 1$, intersect at $\mbf{A}$ and $\phi$ is pyramidal. 

Additionally, the quadratic polynomial $c_0(C_0,C_1)$ is divisible by $a_0(A_0,A_1)$ and $b_0(B_0,B_1)$. 
Therefore, $c_0(C_0,C_1)$ determines a rank-two quadric $\Pi_0\cup\Pi_1$ in the pencil of $u$-surfaces. 
On the other hand, $c_1(C_0,C_1)$ and $q = h(A_0,A_1,B_0,B_1)$ are also  proportional, and define a quadric $Q$. 
In particular, $Q$ contains the lines $s,t\subset \Pi_0$ since $h(A_0,A_1,B_0,B_1)$ vanishes at both. 
Hence, they lie in $Y_0\cap Y_1$. 
Furthermore, we have 
$$
Y_0\cap Y_1 = (\Pi_0\cup\Pi_1) \cap Q = (\Pi_0 \cap Q) \cup (\Pi_1\cap Q) 
= 
s \cup t \cup C
\ ,
$$ 
where $\Pi_1\cap Q = C$ is a plane conic that intersects both $s$ and $t$. 
Moreover, we can write   
$$
\nabla q
= 
\begin{pmatrix}
\frac{\partial h}{\partial s_0} 
& 
\frac{\partial h}{\partial s_1} 
&  
\frac{\partial h}{\partial t_0} 
& 
\frac{\partial h}{\partial t_1} 
\end{pmatrix} 
(A_0,A_1,B_0,B_1) 
\cdot 
D
$$
where $D$ is the Jacobian matrix of the tuple $(A_0,A_1,B_0,B_1)$ in $\R[x_0,x_1,x_2,x_3]^4$, which is scalar-valued. 
Since the partial derivatives of $h$ are homogeneous, $\nabla q$ vanishes at the point $\mbf{A}$ defined by the ideal $(A_0,A_1,B_0,B_1)$. 
Hence, $q$ has a singular point at $\mbf{A}$ and the quadric $Q$ is a cone. 
\end{proof}

In applications, the control points of a pyramidal map can be generated as follows. 

\begin{construction}
\label{construction: pyramidal}
The control points of a pyramidal rational map can be generated as follows: 
\begin{enumerate}
\item Choose a point $\mbf{A}$ in $\P_\R^3$ 
\item For each $0\leq i,j \leq 1$, choose pairwise distinct affine lines $u_{ij}$ in $\P_\R^3$  through $\mbf{A}$ %and not contained in $x_0=0$ 
\item Choose two distinct affine points $\mbf{P}_{ij0}$ and $\mbf{P}_{ij1}$ on $u_{ij}$, different from $\mbf{A}$
\end{enumerate}
\end{construction} 


\subsection{Birational weights and tensor rank criterion}
\label{tensor criterion: pyramidal}

In all the upcoming statements of \cref{sec: pyramidal}, when $\phi$ is pyramidal we assume that $Y_0,Y_1$ are the quadric boundary surfaces. 

\begin{notation}
\label{notation: pyramidal}
Let $\phi$ be pyramidal. 
We denote by 
$\Pi_0$ the plane through the lines $s = \Sigma_0 \cap \Sigma_1$ and $t = T_0 \cap T_1$, which is defined by $\pi_0 = \bs{\pi}_0 \cdot \mbf{x}^T$ for some $\bs{\pi}_0$ in $\R^4$. 
In particular, we find points $(\lambda_0:\lambda_1)$ and $(\mu_0:\mu_1)$ in $\P_\R^1$ such that 
$
\pi_0 
= 
\lambda_0 \, \sigma_0 
+ 
\lambda_1 \, \sigma_1 
= 
\mu_0 \, \tau_0 
+ 
\mu_1 \, \tau_1  
$.
Additionally, for each $0\leq i,j,k \leq 1$ we set 
$$ 
\Delta_{ijk} = 
\frac{1}{
\langle \bs{\pi}_0 , \mbf{P}_{ijk} \rangle
}
\ .
$$ 
\end{notation}

\begin{remark}
For pyramidal maps, $\Delta_{ijk}$ is well-defined for every $0\leq i,j,k\leq 1$. 
Specifically, 
$\Delta_{ijk}$ is not well-defined if and only if $\mbf{P}_{ijk} = \mbf{A}$, a possibility that is excluded by \cref{property: nondegeneracy}. 
More explicitly, if $\mbf{P}_{ijk} = \mbf{A}$ then we find 
$
s_{jk} 
= 
\ovl{\mbf{P}_{0jk}\mbf{P}_{1jk}} 
= 
\ovl{\mbf{A}\mbf{P}_{i^*jk}}
= 
u_{i^*j}
$, 
as well as 
$
t_{ik} 
= 
u_{ij^*}
$.  
\end{remark}

The following is the analogous birationality criterion to \cref{theorem: tensor hexahedral} for pyramidal maps.

\begin{theorem} 
\label{theorem: tensor pyramidal}
Let $\phi$ be pyramidal. Then, $\phi$ is birational of type $(1,1,2)$ if and only if the tensor 
$$
W = \left(
\frac{w_{ijk}}{\Delta_{ijk}}
\right)_{0\leq i,j,k\leq 1}
$$ 
has rank one. 
\end{theorem}

\begin{proof}
By \cite[Theorem $6.1$]{trilinear}, $\phi$ is birational of type $(1,1,2)$ if and only if $\mathbf{f}$ admits syzygies of degrees $(1,0,0)$, $(0,1,0)$, but not $(0,0,1)$.
Since $Y_0$ and $Y_1$ are smooth quadrics, $\mbf{f}$ cannot have a syzygy of degree $(0,0,1)$. 
Therefore, by \cref{lemma: linear syz s} and \cref{linear syz t u} $\phi$ is birational if and only if the matrix rank conditions \cref{matrix: syz s} and \cref{matrix: syz t} hold simultaneously. 
Once more, we rewrite these rank conditions in terms of the flattenings of $W$. 

Recall that we let $0^* = 1$ and $1^* = 0$.  
For each $0\leq i,j,k \leq 1$, we can write   
\begin{gather*} 
\lambda_{i^*}
\langle 
\bs{\sigma}_{i^*} 
, 
\mbf{P}_{ijk}
\rangle 
= 
\langle 
\lambda_{0} 
\,
\bs{\sigma}_{0} 
+
\lambda_{1} 
\,
\bs{\sigma}_{1}  
, 
\mbf{P}_{ijk}
\rangle 
= 
\langle 
\bs{\pi}_0 
, 
\mbf{P}_{ijk}
\rangle 
= 
\Delta_{ijk}^{-1}
\ ,\\ 
\mu_{j^*}
\langle 
\bs{\tau}_{j^*} 
, 
\mbf{P}_{ijk}
\rangle 
= 
\langle 
\mu_{0} 
\,
\bs{\tau}_{0} 
+
\mu_{1} 
\,
\bs{\tau}_{1}  
, 
\mbf{P}_{ijk}
\rangle 
=
\langle 
\bs{\pi}_0 
, 
\mbf{P}_{ijk}
\rangle 
= 
\Delta_{ijk}^{-1}
\ .
\end{gather*} 
Therefore, \cref{matrix: syz s} and \cref{matrix: syz t} are respectively equivalent to 
$$
\rank
\begin{pmatrix}
w_{1jk} \, \Delta_{1jk}^{-1} \\ 
w_{0jk} \, \Delta_{0jk}^{-1}
\end{pmatrix}_{0\leq j,k \leq 1}
= 1
\ \ ,\ \  
\rank
\begin{pmatrix}
w_{i1k} \, \Delta_{i1k}^{-1} \\ 
w_{i0k} \, \Delta_{i0k}^{-1}
\end{pmatrix}_{0\leq i,k \leq 1}
= 1
\ ,
$$ 
which are rank-one conditions on the first two flattenings of $W$. 
By \cite[Proposition $3.11$]{ottaviani_tensor_rank},  $W$ has rank one if and only if these two conditions are satisfied, and the result follows. 
\end{proof} 

\begin{corollary} 
\label{corollary: weight formulas pyramidal}
Let $\phi$ be pyramidal. Then, $\phi$ is birational of type $(1,1,2)$ if and only if 
\begin{equation}
\label{eq: weight formulas pyramidal}
w_{ijk} = \alpha_i \, \beta_j \, \gamma_k \, \Delta_{ijk}
\end{equation}
for some $(\alpha_0:\alpha_1)\times (\beta_0:\beta_1)\times (\gamma_0:\gamma_1)$ in $(\P_\R^1)^3$. 
\end{corollary}

\subsubsection{The contractions of a pyramidal birational map}

\begin{notation}
Let $\phi$ be pyramidal with weights as \cref{eq: weight formulas pyramidal}. 
By \cref{corollary: weight formulas pyramidal}, $\phi$ is birational of type $(1,1,2)$, and by \cref{type pyramidal} the pencil of $u$-surfaces contains the following quadrics:
\vskip2pt
\begin{enumerate}
\item The rank-two quadric $\Pi_0\cup\Pi_1$, where $\Pi_1$ is the plane supporting the conic $C$. 
In particular, $\Pi_1$ is defined by 
$
\pi_1 = \bs{\pi}_1 \cdot \mbf{x}^T
$ 
for some $\bs{\pi}_1$ in $\R^4$
\item The cone (rank-three quadric) $Q$ with apex $\mbf{A} = s \cap t$ through the conic $C$. In particular, we find a $(\nu_0:\nu_1)$ in $\P_\R^1$ such that $Q$ is defined by 
$
q = \nu_0 \, \upsilon_0 + \nu_1 \, \upsilon_1 
$. 
\end{enumerate}  
\end{notation}

The rank-one condition of \cref{theorem: tensor pyramidal} readily determines all the contractions of $\phi$. 

\begin{corollary} 
\label{corollary: contractions pyramidal}
Let $\phi$ be pyramidal with weights as \cref{eq: weight formulas pyramidal}. 
Then, we have 
\begin{equation}
\label{eq: factorization second plane pyramidal}
\langle \bs{\pi}_1 , \mbf{f}\rangle 
= 
h(s_0,s_1,t_0,t_1) 
%\cdot 
\,
c_0(u_0,u_1)
\end{equation}
for some linear $c_0 = c_0(u_0,u_1)$ and bilinear irreducible $h = h(s_0,s_1,t_0,t_1)$. 
Additionally, let    
\begin{equation}
a_0(s_0,s_1)
= 
\begin{vmatrix}
\phantom{-}s_0 & s_1 \\
-\alpha_1 & \alpha_0
\end{vmatrix}
\ ,\ 
b_0(t_0,t_1)
= 
\begin{vmatrix}
\phantom{-}t_0 & t_1 \\
-\beta_1 & \beta_0
\end{vmatrix}
\ ,\ 
c_1(u_0,u_1)
= 
\begin{vmatrix}
\phantom{-}u_0 & u_1 \\
-\gamma_1 & \gamma_0
\end{vmatrix}
\ .
\end{equation}
Then, we have the following:
\vskip2pt
\begin{enumerate}
\item $\phi$ contracts the surface $a_0 = 0$ (resp$.$ $b_0 = 0$) to the line $t$ (resp$.$ $s$)
\item $\phi$ contracts the surface $c_1 = 0$ to the point $\mbf{A} = s\cap t$ 
\item $\phi$ contracts the surface $h = 0$ to the plane conic $C$
\item The image of the surface $c_0 = 0$ is dense in $\Pi_1$
\end{enumerate}
\end{corollary}

\begin{proof}
By \cref{eq: weight formulas pyramidal}, the trilinear polynomial $\langle \bs{\pi}_0,\mbf{f}\rangle$ can be expanded as 
$$
\sum_{0\leq i,j,k\leq 1}
w_{ijk} 
\langle
\bs{\pi}_0 , \mbf{P}_{ijk}
\rangle
s_i t_j u_k
= 
\sum_{0\leq i,j,k\leq 1}
\left( 
\frac{ w_{ijk} }
{ \Delta_{ijk} } 
\right) 
s_i t_j u_k 
= 
\sum_{0\leq i,j,k\leq 1}
(\alpha_i s_i) (\beta_j t_j) (\gamma_k u_k)
= 
a_0 
b_0  
c_1
\ .
$$
By definition we have $\Sigma_i \cap \Pi_0 = \Sigma_0 \cap \Sigma_1 = s$, and the boundary $t$-lines $t_{i0},t_{i1}$ lie in $\Sigma_i$ for each $i = 0,1$. 
Hence, the four boundary $t$-lines intersect $\Pi_0$ at $s$. 
Therefore, as the image by $\phi$ of the surface $b_0 = 0$ lies in $\Pi_0$, it follows that $\phi$ contracts it to $s$. 
Similarly, it follows that $\phi$ contracts the surface $a_0=0$ to $t$. 
Additionally, the image of $c_1 = 0$ also lies in $\Pi_0$. 
Since the four boundary $u$-lines meet $\Pi_0$ at $\mbf{A}$, we conclude that 
$\phi$ contracts $c_1 = 0$ to $\mbf{A}$. 

On the other hand, by \cref{type pyramidal} the base locus of $\phi^{-1}$ is $Y_0\cap Y_1 = s\cup t\cup C$, hence defined by the ideal $(\upsilon_0 , \upsilon_1)\subset \R[x_0,x_1,x_2,x_3]$. 
Since $\phi$ is birational, we find 
$$
(\upsilon_0(\mbf{f}) , \upsilon_1(\mbf{f}))
= 
a_0 
b_0 
c_1 
h
\cdot 
(u_0 , u_1)
$$
for some $h = h(s_0,s_1,t_0,t_1)$ bilinear. 
In particular, the pullback ideal $(\upsilon_0(\mbf{f}) , \upsilon_1(\mbf{f}))\subset R$ defines the union of the surfaces $a_0 = 0$, $b_0 = 0$, $c_1 = 0$, and $h= 0$. 
Therefore, $\phi$ must contract $h=0$ to the conic $C$.  
Since $\Pi_1$ supports this conic, we find the factorization \cref{eq: factorization second plane pyramidal}.
In particular, the image of $c_0 = 0$ is dense in $\Pi_1$. 
%Additionally, since $\phi$ is dominant the intersection points of the boundary $u$-lines with $\Pi_1$ are not colinear, and the image of $c_0 = 0$ is dense in $\Pi_1$.
%Let $h = 0$ be this surface, for some multihomogeneous $h$ in $R$.  
%Then, the ideal $(c_1,h)\subset R$ defines a component of the base locus of $\phi$, since $C$ and $\mbf{A}$ are disjoint.  
%By \cref{theorem: base locus classification}, it follows that $h = h(s_0,s_1,t_0,t_1)$ is bilinear and irreducible. 
%In particular, the pullback of the plane $\Pi_1$ admits the factorization \cref{eq: factorization second plane pyramidal} for some linear $c_0 = c_0(u_0,u_1)$.  
%Furthermore, since $\phi$ is dominant the intersection points of the boundary $u$-lines with $\Pi_1$ are not colinear, and the image of $c_0 = 0$ is dense in $\Pi_1$.  
\end{proof}

\subsection{Inverse and base locus}
\label{inverse: pyramidal}

In this subsection, we derive formulas for the inverse of a pyramidal birational map.
Additionally, we describe the base loci and blow-ups. 

\begin{theorem} 
\label{theorem: inverse pyramidal}
Let $\phi$ be pyramidal with weights as \cref{eq: weight formulas pyramidal}. 
Then, $\phi^{-1}$ is given by 
$$
(x_0 : x_1 : x_2 : x_3) 
\mapsto 
