\section{Scaffold birational maps} 
\label{sec: scaffold}

In this section, we study the third family of birational maps: the class of scaffold birational maps. 
%illustrated in \cref{fig: constraints} bottom-left. 
%Again, this name is motivated by the geometry of trilinear birational maps of types $(1,2,2)$, $(2,1,2)$ and $(2,2,1)$. 
%A ``scaffold'' typically consists of four lines $s_{00},s_{10},s_{01},s_{11}$ that support a sequence of planar platforms, like the $s$-parametric planes.  

\begin{definition}
\label{scaffold}
A trilinear rational map is scaffold if 
%it satisfies \cref{property: nondegeneracy} and
all the boundary surfaces are quadrics except for one of the three parameters, for which:
\begin{enumerate}
\item The two boundary surfaces are planes, that intersect at a line $\ell$ 
\item The four boundary lines intersect two lines $r_0,r_1$, and these two intersect $\ell$
\end{enumerate}
\end{definition}

Given four pairwise skew lines in $\P^3$, not lying on a common quadric, there are exactly two secant lines %(counting multiplicity) 
that intersect the four of them. 
%If the boundary $t$- and $u$-surfaces are quadrics, then the  boundary $s$-lines are mutually nonintersecting.
The two secants of the boundary lines are precisely $r_0$ and $r_1$. 


\subsection{Geometric constraint}
\label{geometric constraint: scaffold}

As in \cref{geometric constraint: pyramidal}, we begin proving that a general birational map of type either $(1,2,2)$, $(2,1,2)$, or $(2,2,1)$ is scaffold. 
Once more, we restrict to type $(1,2,2)$. 

\begin{proposition} 
\label{type scaffold}
If $\phi$ is a general birational map of type $(1,2,2)$, then it is scaffold. Moreover,  
$$
T_0 \cap T_1 = s \cup r_0 \cup r_1 \cup y 
\ ,\ 
Y_0 \cap Y_1 = s \cup r_0 \cup r_1 \cup z 
\ ,
$$
where:
\vskip2pt
\begin{enumerate}
\item $s = \Sigma_0 \cap \Sigma_1$ is a line
\item $r_0,r_1$ are the unique two lines in $\P^3$ that meet $s_{jk}$ for every $0\leq j,k \leq 1$ 
\item $y$ is the line through the points $u_{00}\cap u_{01}$ and $u_{10}\cap u_{11}$
\item $z$ is the line through the points $t_{00}\cap t_{01}$ and $t_{10}\cap t_{11}$
\end{enumerate}
\end{proposition} 

\begin{proof}
First, since $\phi$ is general \cref{property: nondegeneracy} is satisfied. 
By \cite[Theorem $5.6$]{trilinear}, we find 
\begin{equation} 
(f_0,f_1,f_2,f_3)  : \mathfrak{N}^\infty  = (a_0 , b_0 , c_0) \cap (a_1 , b_1 , c_1) \cap (b_2 , c_2) 
\end{equation}
for some linear $a_i = a_i(s_0,s_1)$, $b_j = b_j(t_0,t_1)$, and $c_k = c_k(u_0,u_1)$.  
Additionally, $\phi^{-1}$ is defined by 
$$
(x_0,x_1,x_2,x_3) \mapsto (A_0:A_1)\times (B_0:B_1)\times (C_0:C_1)
$$
for some linear $A_i = A_i(\mbf{x})$ and quadratic $B_j = B_j(\mbf{x})$ and $C_k = C_k(\mbf{x})$. 
In particular, we find % the pullback ideal of $I$ satisfies 
$$
(f_0(A_0,A_1,B_0,B_1,C_0,C_1) \, , \, \ldots \, , \, f_3(A_0,A_1,B_0,B_1,C_0,C_1)) 
= 
H
\cdot 
(x_0 , x_1 , x_2 , x_3)
$$ 
for some quartic form $H = H(\mbf{x})$. 
Therefore, the ideals in $\R[x_0,x_1,x_2,x_3]$
$$
(a_0(A_0,A_1),b_0(B_0,B_1),c_0(C_0,C_1)) 
,
(a_1(A_0,A_1),b_1(B_0,B_1),c_1(C_0,C_1)) 
,
(b_2(B_0,B_1),c_2(C_0,C_1))
$$ 
are principal and respectively generated by two linear and one quadratic forms. 
Thus, 
for each $i=0,1$ the polynomials $b_i(B_0,B_1)$ and $c_i(C_0,C_1)$ are divisible by $a_i(A_0,A_1)$, and we can write 
$$
b_i(B_0,B_1) = a_i(A_0,A_1) \, F_i 
\ ,\ 
c_i(C_0,C_1) = a_i(A_0,A_1) \, G_i 
$$  
for some linear forms $F_i = F_i(\mbf{x})$ and $G_i = G_i(\mbf{x})$. 
Therefore,  
\begin{gather*}
(B_0,B_1) = (b_0(B_0,B_1), b_1(B_0,B_1)) 
= 
%( a_0(A_0,A_1) \, F_0 , a_1(A_0,A_1) \, F_1 ) = \\[2pt]
( A_0 , A_1 ) 
\cap 
( a_0(A_0,A_1) , F_1 ) 
\cap 
( F_0 , a_1(A_0,A_1) ) 
\cap 
( F_0 , F_1 )
\ ,
\end{gather*} 
where we have used that $(A_0,A_1) = ( a_0(A_0,A_1) , a_1(A_0,A_1) ) $. 
Analogously,  
$$
(C_0,C_1) 
= 
( A_0 , A_1 ) 
\cap 
( a_0(A_0,A_1) , G_1 ) 
\cap 
( G_0 , a_1(A_0,A_1) ) 
\cap 
( G_0 , G_1 )
\ .
$$
Therefore, the two intersections $T_0\cap T_1$ and $Y_0\cap Y_1$ define unions of four lines. 
Since smooth quadrics are doubly ruled (i$.$e$.$ isomorphic to $\P^1\times\P^1$), and three skew lines determine a unique quadric, it follows that in each intersection there is a pair of lines in each ruling of the corresponding boundary surfaces. 
Moreover, by definition $\Sigma_0,\Sigma_1$ are planes and the ideal $(A_0,A_1)$ determines $s = \Sigma_0 \cap \Sigma_1$.  
Hence, the line $y$ (resp$.$ $z$) defined by $(F_0,F_1)$ (resp$.$ $(G_0,G_1)$) lies in the same ruling of $s$ in $T_j$ (resp$.$ $Y_k$). 
Additionally, for each $0 \leq i,j \leq 1$ the line $u_{ij}\subset T_j$ intersects $s$, since $u_{ij}\subset \Sigma_i$.  
Thus, $s$ and $u_{ij}$ belong to different rulings, and $y$ intersects $u_{ij}$ as well. 
Since $u_{i0},u_{i1}\subset \Sigma_i$ and $y\not\subset \Sigma_i$, $y$ must meet the point $u_{i0} \cap u_{i1}$. 
Therefore, $y$ is as claimed in the statement. 
With a parallel argument, we derive that $z$ is also as claimed. 

We conclude proving that the lines $r_0,r_1$ lie in both intersections.  
The line $s_{jk}\subset T_j$ (resp$.$ $s_{jk}\subset Y_k$) does not meet $s$ for any $0\leq j,k \leq 1$, so they lie in the same ruling. 
Therefore, the lines defined by 
$
( a_0(A_0,A_1) , F_1 ) 
$ and 
$
( F_0 , a_1(A_0,A_1) )
$ 
(resp$.$ 
$
( a_0(A_0,A_1) , G_1 ) 
$ and 
$
( G_0 , a_1(A_0,A_1) ) 
$)
must intersect the four boundary $s$-lines. 
Hence, they are the unique two with this property, namely $r_0$ and $r_1$. 
Since $r_0, r_1$ also  intersect $s$, it follows that $\phi$ is scaffold.
\end{proof}

In practice, the control points of a scaffold map can be generated with the following construction. 

\begin{construction}
\label{construction: scaffold}
The control points of a scaffold rational map can be generated as follows: 
\vskip2pt
\begin{enumerate}
\item Choose a line $s$ in $\P_\R^3$
\item Choose two skew lines $r_0,r_1$ in $\P_\R^3$ intersecting $s$
\item For each $0\leq j,k \leq 1$, choose pairwise distinct affine lines $s_{jk}$ meeting both $r_0,r_1$% and not contained in $x_0 = 0$
\item Choose distinct planes $\Sigma_0,\Sigma_1$ through $s$, not containing $r_0,r_1$, such that $\Sigma_i \cap s_{jk}$ is affine
\item For each $0\leq i,j,k \leq 1$, define $\mbf{P}_{ijk} = \Sigma_i \cap s_{jk}$ 
\end{enumerate}
\end{construction} 

\subsection{Birational weights and tensor rank criterion}
\label{tensor criterion: scaffold}

In all the upcoming statements of \cref{sec: scaffold}, when $\phi$ is scaffold we assume that $\Sigma_0,\Sigma_1$ are the planar boundary surfaces. 

\begin{notation}
Let $\phi$ be scaffold, and maintain the notation of items $1$-$4$ in \cref{type scaffold}. 
Then, we find planes $\Pi_i, \Theta_j, P_k$ for each $0\leq i,j,k\leq 1$, respectively defined by 
$
\pi_i = \bs{\pi}_i \cdot \mbf{x}^T
$, 
$
\theta_j = \bs{\theta}_j \cdot \mbf{x}^T 
$, 
$
\rho_k = \bs{\rho}_k \cdot \mbf{x}^T
$ 
for some $\bs{\pi}_i, \bs{\theta}_j, \bs{\rho}_k$ in $\R^4$, such that: 
\vskip2pt
\begin{enumerate}
\item The plane $\Pi_i$ is defined by the lines $s$ and $r_i$. In particular, we find a $(\lambda_{0i}:\lambda_{1i})$ in $\P_\R^1$ such that 
$
\pi_i = \lambda_{0i} \, \sigma_0 + \lambda_{1i} \, \sigma_i
$
\item The plane $\Theta_j$ is defined by the lines $y$ and $r_j$
\item The plane $P_k$ is defined by the lines $z$ and $r_k$
\end{enumerate} 
\vskip2pt
\noindent Additionally, for each $l = 0,1$ we define 
$$ 
