}
\ \ ,\ \ 
\Delta_{ijk}(l,z) = 
\frac{1}{
\langle \bs{\rho}_l , \mbf{P}_{ijk} \rangle
}
\ .
$$ 
%Notice that $\Delta_{ijk}(l,y)$ (resp$.$ $\Delta_{ijk}(l,z)$) is not well defined if and only if $\mbf{P}_{ijk}$ lies on the line $r_l$, a possibility that we exclude in \cref{construction: scaffold}.  
\end{notation}

\begin{remark}
\label{remark: deltas scaffold}
For scaffold maps, both $\Delta_{ijk}(l,y)$ and $\Delta_{ijk}(l,z)$ are well-defined for every $0\leq i,j,k\leq 1$. 
Specifically, 
$\Delta_{ijk}(l,y)$ (resp$.$ $\Delta_{ijk}(l,z)$) is not well-defined if and only if $\mbf{P}_{ijk}$ lies on the line $r_l$.  
If this is the case, namely if $\mbf{P}_{ijk} = \Sigma_i \cap s_{jk}$ lies on $r_l$, it follows that $\Sigma_i = \text{Plane}(s,r_l)$. 
Hence, we can write 
$\mbf{P}_{ij'k'} = 
\Sigma_i \cap s_{j'k'} = 
\text{Plane}(s,r_l)
\cap
s_{j'k'}
= 
r_l
\cap
s_{j'k'} 
$ for every $0\leq j',k'\leq 1$. 
Therefore, $\mbf{P}_{i00},\mbf{P}_{i10},\mbf{P}_{i01}$, and $\mbf{P}_{i11}$ are aligned, and $\Sigma_i = r_l$ against \cref{property: nondegeneracy}.
\end{remark}

