$$
for some linear $c_2 = c_2(u_0,u_1)$.
In particular, $\phi$ contracts $c_2 = 0$ to $y$ and we find the factorizations 
$
\langle 
\bs{\theta}_0 , \mbf{f}
\rangle 
= 
a_0 b_0 c_2
$,
$
\langle 
\bs{\theta}_1 , \mbf{f}
\rangle 
= 
a_1 b_1 c_2
$ 
for some linear $b_j = b_j(t_0,t_1)$, for each $j = 0,1$. 
Equivalently, the tensors $W(0,y)$, $W(1,y)$ have rank one. 
With a parallel argument, we conclude that $W(k,z)$ has rank one for each $k = 0,1$. 
\end{proof}

\begin{corollary}
\label{corollary: weight formulas scaffold}
Let $\phi$ be scaffold. 
Then, $\phi$ is birational of type $(1,2,2)$ if and only if one, and therefore all up to a nonzero scalar multiplying all the weights, of the following conditions holds:
\vskip2pt 
\begin{enumerate}
\item $w_{ijk} = \alpha_{i0} \, \beta_{j0} \, \gamma_{k2} \, \Delta_{ijk}(0,y)$ for each $0\leq i,j,k\leq 1$
\item $w_{ijk} = \alpha_{i1} \, \beta_{j1} \, \gamma_{k2} \, \Delta_{ijk}(1,y)$ for each $0\leq i,j,k\leq 1$
\item $w_{ijk} = \alpha_{i0} \, \beta_{j2} \, \gamma_{k0} \, \Delta_{ijk}(0,z)$ for each $0\leq i,j,k\leq 1$
\item $w_{ijk} = \alpha_{i1} \, \beta_{j2} \, \gamma_{k1} \, \Delta_{ijk}(1,z)$ for each $0\leq i,j,k\leq 1$
\end{enumerate}
\vskip2pt 
\noindent for some $(\alpha_{0i}:\alpha_{1i})$, $(\gamma_{0j}:\beta_{1j})$, $(\gamma_{0k}:\gamma_{1k})$ in $(\P_\R^1)^3$.
\end{corollary}

\subsubsection{The contractions of a scaffold birational map}

\begin{notation}
Let $\phi$ be scaffold with weights as in \cref{corollary: weight formulas scaffold}. 
In particular, $\phi$ is birational of type $(1,2,2)$, and by \cref{type scaffold} we have the following:
\vskip2pt
\begin{enumerate}
\item The rank-two quadrics $\Pi_0\cup\Theta_1$ and $\Pi_1\cup\Theta_0$ belong to the pencil of $t$-surfaces
\item The rank-two quadrics $\Pi_0\cup P_1$ and $\Pi_1\cup P_0$ belong to the pencil of $u$-surfaces
\item The unique smooth quadric $Q$ defined by the lines $s$, $y$, and $z$ belongs to the two pencils of $t$- and $u$-surfaces. In particular, $Q$ is defined by a quadratic form $q = q(\mbf{x})$, and we find points $(\mu_0:\mu_1)$ in $(\nu_0:\nu_1)$ in $\P_\R^1$ such that 
$ 
q = \mu_0 \, \tau_0 + \mu_1 \, \tau_1
=
\nu_0 \, \upsilon_0 + \nu_1 \, \upsilon_1
$
\end{enumerate}  
\end{notation}

As for the class of pyramidal maps, the rank-one conditions of \cref{theorem: tensor scaffold} determine the contractions of a scaffold birational map.

\begin{corollary}
\label{corollary: contractions scaffold}
Let $\phi$ be scaffold with weights as in \cref{corollary: weight formulas scaffold}, and let 
\begin{equation}
a_i(s_0,s_1)
= 
\begin{vmatrix}
\phantom{-}s_0 & s_1 \\
-\alpha_{1i} & \alpha_{0i}
\end{vmatrix}
\ ,\ 
b_j(t_0,t_1)
= 
\begin{vmatrix}
\phantom{-}t_0 & t_1 \\
-\beta_{1j} & \beta_{0j}
\end{vmatrix}
\ ,\ 
c_k(u_0,u_1)
= 
\begin{vmatrix}
\phantom{-}u_0 & u_1 \\
-\gamma_{1k} & \gamma_{0k}
\end{vmatrix}
\end{equation}
for $i=0,1$ and $0\leq j,k\leq 2$. 
Then, we have the following:
\vskip2pt
\begin{enumerate}
\item For each $i = 0,1$, $\phi$ contracts the surface $a_i = 0$ to the line $r_i$
\item $\phi$ contracts the surface $b_2 = 0$ to the line $z$ 
\item $\phi$ contracts the surface $c_2 = 0$ to the line $y$
\item For each $j = 0,1$, the image of the surface $b_j = 0$ is dense in the plane $\Theta_j$
\item For each $k = 0,1$, the image of the surface $c_k = 0$ is dense in the plane $P_k$
\end{enumerate}
\end{corollary}

