\section{Tripod birational maps}
\label{sec: tripod}

We conclude addressing the last, and geometrically most complex, family of birational maps: the class of tripod birational maps. 
%, illustrated in \cref{fig: constraints} bottom-right. 
%As for the former classes, this name is motivated by the geometry of trilinear birational maps of type $(2,2,2)$. 

\begin{definition}
\label{tripod}
A trilinear rational map is tripod if all the boundary surfaces are quadrics and: 
\begin{enumerate}
\item The four boundary $s$-lines (resp$.$ $t$-lines and $u$-lines) intersect a line $s$ (resp$.$ $t$ and $u$) 
\item The three lines $s,t,u$ intersect at a point $\mbf{A}$
\item All the boundary lines intersect a plane conic $C$ which intersects the three lines $s,t$, and $u$
\end{enumerate}
\end{definition}

\subsection{Geometric constraint} 

As in \cref{geometric constraint: pyramidal} and \cref{geometric constraint: scaffold}, we begin proving that a general birational map of type $(2,2,2)$ is tripod. 

\begin{proposition} 
\label{type tripod}
If $\phi$ is a general birational map of type $(2,2,2)$, then it is tripod. 
Moreover, 
$$
\Sigma_0 \cap \Sigma_1 = t \cup u \cup C 
\ ,\ 
T_0 \cap T_1 = s \cup u \cup C 
\ ,\ 
Y_0 \cap Y_1 = s \cup t \cup C 
\ .
$$
\end{proposition} 

\begin{proof}
Since $\phi$ is general  \cref{property: nondegeneracy} is satisfied, and by \cite[Theorem $5.8$]{trilinear} we have
\begin{equation}
\label{eq: (222) BI} 
(f_0,f_1,f_2,f_3) : \mathfrak{N}^\infty  = (a_0 , b_0 , c_0) \cap (a_1^2 , b_1^2 , c_1^2 , a_1 b_1 , a_1 c_1 , b_1 c_1 , a_1 b_0 c_0 + a_0 b_1 c_0 + a_0 b_0 c_1 )
\end{equation}
for some linear $a_i = a_i(s_0,s_1)$, $b_j = b_j(t_0,t_1)$, $c_k = c_k(u_0,u_1)$. 
With the notation of \cref{eq: inverse map} for $\phi^{-1}$, 
$$
(f_0(A_0,A_1,B_0,B_1,C_0,C_1) \, , \, \ldots \, , \, f_3(A_0,A_1,B_0,B_1,C_0,C_1)) 
= 
F
\cdot 
(x_0 , 
x_1 , 
x_2 , 
x_3 )
$$ 
for some quintic form  $F = F(\mbf{x})$. 
In particular, $F=0$ defines the projection to $\P^3$ of the exceptional divisor $E$ of the blow-up $\Gamma\subset (\P^1)^3\times\P^3$ of $(\P^1)^3$ along the base locus of $\phi$. 
By \cref{eq: (222) BI},  $E$ has two irreducible components. 

Let 
$\Tilde{a}_i = a_i(A_0,A_1)$, $\Tilde{b}_j = b_j(B_0,B_1)$, and $\Tilde{c}_k = c_k(C_0,C_1)$ 
for each $0\leq i,j,k\leq 1$. 
Then, the components of $E$ project to the surfaces in $\P^3$ defined by $G_0 = 0$ and $G_1 = 0$, where 
$$
G_0 = 
\gcd 
\left(
\Tilde{a}_0, \Tilde{b}_0 , \Tilde{c}_0
\right)
\ ,\ 
G_1 = 
\gcd 
\left(
{\Tilde{a}_1}^2, \Tilde{b}_1^2 , \Tilde{c}_1^2, 
\Tilde{a}_1 \Tilde{b}_1, 
\Tilde{a}_1 \Tilde{c}_1, 
\Tilde{b}_1 \Tilde{c}_1, 
\Tilde{a}_1 \Tilde{b}_0 \Tilde{c}_0 + 
\Tilde{a}_0 \Tilde{b}_1 \Tilde{c}_0 + 
\Tilde{a}_0 \Tilde{b}_0 \Tilde{c}_1
\right)
$$ 
and $F = G_0 G_1$. 
In particular, since 
$
1 \leq \deg G_0 \leq 2
$ 
it follows that $\deg G_1\geq 3$. 
Therefore, the degree of 
$
G' = 
\gcd
(
\Tilde{a}_1^2 , 
\Tilde{b}_1^2 , 
\Tilde{c}_1^2 , 
\Tilde{a}_1 \Tilde{b}_1 , 
\Tilde{a}_1 \Tilde{c}_1 , 
\Tilde{b}_1 \Tilde{c}_1 
)
$
is also at least three. 
It follows that $\deg G' = 4$, and $\Tilde{a}_1,\Tilde{b}_1,\Tilde{c}_1$ are proportional. 
On the other hand, if $G_0$ is quadratic then $\Tilde{a}_0,\Tilde{b}_0,\Tilde{c}_0$ are also proportional, implying 
$$
\Tilde{a}_1 \Tilde{b}_0 \Tilde{c}_0 + \Tilde{a}_0 \Tilde{b}_1 \Tilde{c}_0 + \Tilde{a}_0 \Tilde{b}_0 \Tilde{c}_1
= 
\lambda_1
\, 
\Tilde{a}_1 \Tilde{a}_0^2 
=
\lambda_2
\, 
\Tilde{b}_1 \Tilde{b}_0^2
= 
\lambda_3
\, 
\Tilde{c}_1 \Tilde{c}_0^2
$$
for some nonzero $\lambda_1,\lambda_2,\lambda_3$. 
Since $\gcd(A_0,A_1) = 1$ we find 
$
G_1 = \gcd(\Tilde{a}_1^2,\Tilde{a}_1 \Tilde{a}_0^2) 
= 
\Tilde{a}_1
$, yielding a contradiction. 
Hence, we must have $(\deg G_0,\deg G_1) = (1,4)$. 

Therefore, $\Tilde{a}_1,\Tilde{b}_1$, and $\Tilde{c}_1$ are proportional to a quadratic form $q = q(\mbf{x})$, we have $G_1 = q^2$, and moreover 
$
\Tilde{a}_0 = \pi_1 \pi
$, 
$
\Tilde{b}_0 = \pi_2 \pi 
$, 
$ 
\Tilde{c}_0 = \pi_3 \pi
$
for some linear forms $\pi = \pi(\mbf{x})$ and $\pi_r = \pi_r(\mbf{x})$ for $r = 1,2,3$.  
In particular, we can write 
$$
(A_0,A_1) 
= 
(\Tilde{a}_0,\Tilde{a}_1)
= 
(\pi_1 \pi, q)
= 
(\pi_1, q) \cap (\pi, q)
$$
and 
$
\Tilde{a}_1 \Tilde{b}_0 \Tilde{c}_0 + \Tilde{a}_0 \Tilde{b}_1 \Tilde{c}_0 + \Tilde{a}_0 \Tilde{b}_0 \Tilde{c}_1 
= 
\pi^2 
q
\, 
\left(
\omega_1 \, \pi_2 \pi_3 + 
\omega_2 \, \pi_1 \pi_3 + 
\omega_3 \, \pi_1 \pi_2
\right)
$
for some nonzero $\omega_1,\omega_2,\omega_3$. 
Since the polynomial above is divisible by $G_1 = q^2$, and $q$ and $\pi$ are coprime, it follows that 
$
\omega_1 \, \pi_2 \pi_3 + 
\omega_2 \, \pi_1 \pi_3 + 
\omega_3 \, \pi_1 \pi_2
$ 
is proportional to $q$. 
Hence,  
$$
(\pi_1,q)
= 
(\pi_1, \pi_2 \pi_3)
= 
(\pi_1, \pi_2) \cap (\pi_1, \pi_3)
\ . 
$$
With parallel arguments, we derive 
$$
(B_0,B_1) 
=
(\pi_2,\pi_1) 
\cap
(\pi_2,\pi_3) 
\cap
(\pi,q)
\ ,\ 
(C_0,C_1) 
=
(\pi_3,\pi_1) 
\cap
(\pi_3,\pi_2) 
\cap
(\pi,q)
\ \ .
$$
Let $(\pi_2,\pi_3), (\pi_1,\pi_3)$, and $(\pi_1,\pi_2)$ respectively define lines $s,t$, and $u$, and let $(\pi,q)$ define a plane conic $C$. 
By definition, $s\cap t\cap u = \mbf{A}$ and the four boundary $s$-lines (resp$.$ $t$- and $u$-lines) intersect $s$ (resp$.$ $t$ and $u$) since they lie in the base loci $T_0\cap T_1$ and $Y_0\cap Y_1$ (resp$.$ in $\Sigma_0\cap \Sigma_1$, $Y_0\cap Y_1$ and $\Sigma_0\cap \Sigma_1$, $T_0\cap T_1$). 
Additionally, $C$ intersects $s,t$, and $u$. 
Moreover, $C$ is intersected by all the boundary lines, since it lies in the base locus of all the parametric surfaces. 
Therefore, $\phi$ is tripod. 
\end{proof}

Let $\ell$ and $C$ be respectively a line and a plane conic in $\P^3$, such that $\ell\cap C = \mbf{Q}_1$ is a point. 
Additionally, let $\mbf{P}$ be a general point in $\P^3$. 
Then, the plane through $\mbf{P}$ and $\ell$ intersects $C$ at exactly two points $\mbf{Q}_1,\mbf{Q}_2$. 
In particular, $\ovl{\mbf{P}\mbf{Q}_2}$ is the unique line through $\mbf{P}$ that intersects $\ell$ and $C$ at distinct points. 
In practice, the control points of a tripod map can be generated as follows. 

\begin{construction}
\label{construction: tripod}
The control points of a tripod rational map can be generated as follows: 
\vskip2pt
\begin{enumerate}
\item Choose a point $\mbf{A}$ in $\P_\R^3$ 
\item Choose three distinct lines $s,t,u$ in $\P_\R^3$ through $\mbf{A}$ 
\item Choose a plane $\Pi\subset \P_\R^3$ not containing any of the lines $s,t,u$
\item Choose a plane conic $C\subset \Pi$ through $s\cap \Pi$, $t\cap \Pi$, and $u\cap \Pi$
\item Choose an affine control point $\mbf{P}_{000}$ not lying on $s,t,u$ or $\Pi$
\item Define $s_{00}$ (resp$.$ $t_{00},u_{00}$) as the line through $\mbf{P}_{000}$ that intersects $s$ (resp$.$ $t,u$) and $C$ at distinct points
%$C\backslash s$ (resp$.$ $C\backslash t$ and $C\backslash u$)
%\item Define $t_{00}$ as the line through $\mbf{P}_{000}$ that intersect $t$ and  $C\backslash t$  
%\item Define $u_{00}$ as the line through $\mbf{P}_{000}$ that intersects $u$ and $C\backslash u$
\item Choose affine control points $\mbf{P}_{100}$, $\mbf{P}_{010},\mbf{P}_{001}$, respectively on $s_{00},t_{00},u_{00}$, all distinct and not lying on $s,t,u$
\item Define $t_{10},u_{10}$ (resp$.$ $s_{10},u_{01}$ and $s_{01},t_{01}$) as in $6$ from the point $\mbf{P}_{100}$ (resp$.$ $\mbf{P}_{010}$ and $\mbf{P}_{001}$)
%\item Define $s_{10}$ (resp$.$ $u_{01}$) as in $6$ (resp$.$ $8$) from the point $\mbf{P}_{010}$
%\item Define $s_{01}$ (resp$.$ $t_{01}$) as in $6$ (resp$.$ 7) from the point $\mbf{P}_{001}$
\item Define $\mbf{P}_{011} = t_{01}\cap u_{01}$, $\mbf{P}_{101} = s_{01}\cap u_{10}$, and $\mbf{P}_{110} = s_{10}\cap t_{10}$
\item Define $s_{11}, t_{11}, u_{11}$ as in $6$ respectively from the points $\mbf{P}_{011},\mbf{P}_{101}, \mbf{P}_{110}$
\item Define $\mbf{P}_{111} = s_{11}\cap t_{11}\cap u_{11}$
\end{enumerate}
\end{construction}

In \cref{example: quadcube} we illustrate how  \cref{construction: tripod} can be used in practice with an example. 

\subsection{Birational weights and tensor rank criterion} 
\label{tensor criterion: tripod}

\begin{notation}
Let $\phi$ be tripod. 
We denote by $\Pi_1$ (resp$.$ $\Pi_2$ and $\Pi_3$) the plane through $t,u$ (resp$.$ $s,u$ and $s,t$), which is defined by 
$\pi_r = \bs{\pi}_r \cdot \mbf{x}^T
$ for $r=1$ (resp$.$ $r=2$ and $r=3$) and some $\bs{\pi}_r$ in $\R^4$. 
Additionally, for each $0\leq i,j,k\leq 1$, we define 
$$ 
\Delta_{ijk}(r) = 
\frac{1}{
\langle \bs{\pi}_r , \mbf{P}_{ijk} \rangle
}
\ .
$$ 
\end{notation}

\begin{remark}
For tripod maps, $\Delta_{ijk}(r)$ is  well-defined for every $0\leq i,j,k\leq 1$ and $r = 1,2,3$. 
Specifically, 
$\Delta_{ijk}(r)$ is not well-defined if and only if $\mbf{P}_{ijk}$ lies on the plane $\Pi_r$. 
Without loss of generality, let $r = 1$. 
Then, the boundary line $t_{ik}$ (resp$.$ $u_{ij}$) also lies in $\Pi_1$, since it intersects $t$ (resp$.$ $u$) and $\Pi_1 = \text{Plane}(t,u)$. 
Similarly, the control point $\mbf{P}_{ij^*k}$ (resp$.$ $\mbf{P}_{ijk^*}$) lies in $\Pi_1$, and the line $u_{ij^*}$ (resp$.$ $t_{ik^*}$) as well for the same reasons as before. 
Therefore, the four control points $\mbf{P}_{i00}, \mbf{P}_{i10}, \mbf{P}_{i01}$, and $\mbf{P}_{i11}$ are coplanar, yielding a contradiction with the fact that $\Sigma_i$ is a smooth quadric.
\end{remark}

%As in \cref{tensor criterion: hexahedral}, \cref{tensor criterion: pyramidal}, and \cref{tensor criterion: scaffold}, the birationality of a tripod map is equivalent to a rank-one condition on a $2\times 2\times 2$ tensor. 

\begin{theorem} 
\label{theorem: tensor tripod}
Let $\phi$ be tripod. The following are equivalent:
\vskip2pt
\begin{enumerate}
\item $\phi$ is birational of type $(2,2,2)$
\item One of the three tensors 
$$
W(r) = \left( \frac{w_{ijk}}{\Delta_{ijk}(r)} \right)_{0\leq i,j,k \leq 1} 
$$
for each $r = 1,2,3$, has rank one 
\item The three tensors above have rank one 
\end{enumerate}
\end{theorem} 

\begin{proof}
First, we prove that 1 implies both 2 and 3. 
For each $r=1,2,3$, the tensor $W(r)$ encodes the coefficients of the trilinear polynomial 
$
\langle \bs{\pi}_r , \mbf{f}\rangle
$,  
%= 
%\sum_{0\leq i,j,k\leq 1}
%w_{ijk} \, \langle \bs{\pi}_r , \mbf{P}_{ijk}\rangle 
%\, 
%s_i t_j u_k 
%= 
%\sum_{0\leq i,j,k\leq 1}
%\left(
%\frac{w_{ijk}}{\Delta_{ijk}(r)} 
%\right)
%\, 
%s_i t_j u_k , 
which defines the pullback by $\phi$ of $\Pi_r$. 
By \cref{type tripod}, the lines $s,t,u$ are irreducible components of the base locus of $\phi^{-1}$. 
Hence, $\phi$ contracts some surfaces in $(\P^1)^3$ to each of them. 
Since each plane $\Pi_1,\Pi_2,\Pi_3$ contains two of these lines, $\langle \bs{\pi}_r , \mbf{f} \rangle$ admits two factors that must be linear. Equivalently, $W(r)$ has rank one. 

We continue proving that $2$ implies $3$. 
Without loss of generality, we assume that
$
W(1) = 
(\alpha_{00},\alpha_{10}) \otimes (\beta_{01},\beta_{11}) \otimes (\gamma_{01},\gamma_{11})
$, yielding the factorization 
$
