\begin{corollary}
\label{corollary: weight formulas tripod}
Let $\phi$ be tripod. 
Then, $\phi$ is birational of type $(2,2,2)$ if and only if one, and therefore all up to a nonzero scalar multiplying all the weights, of the following conditions holds:
\vskip2pt 
\begin{enumerate}
\item $w_{ijk} = \alpha_{i0} \, \beta_{j1} \, \gamma_{k1} \, \Delta_{ijk}(1)$ for each $0\leq i,j,k\leq 1$
\item $w_{ijk} = \alpha_{i1} \, \beta_{j0} \, \gamma_{k1} \, \Delta_{ijk}(2)$ for each $0\leq i,j,k\leq 1$
\item $w_{ijk} = \alpha_{i1} \, \beta_{j1} \, \gamma_{k0} \, \Delta_{ijk}(3)$ for each $0\leq i,j,k\leq 1$
\end{enumerate}
\vskip2pt 
\noindent for some $(\alpha_{0i}:\alpha_{1i})$, $(\gamma_{0j}:\beta_{1j})$, $(\gamma_{0k}:\gamma_{1k})$ in $\P_\R^1$.
\end{corollary}

