\end{pmatrix}
\ ,\ 
\mbf{P}_{110} = 
\begin{pmatrix}
1, & \frac{4}{5}, & 0, & 1
\end{pmatrix}
\ ,\\[6pt] 
\setlength\arraycolsep{1pt}
\mbf{P}_{001} = 
\begin{pmatrix}
1, & -\frac{11}{10}, & 0, & \frac{9}{4}
\end{pmatrix}
\ ,\ 
\mbf{P}_{101} = 
\begin{pmatrix}
1, & 0, & -\frac{4}{5}, & 3
\end{pmatrix}
\ ,\ 
\mbf{P}_{011} = 
\begin{pmatrix}
1, & 0, & \frac{3}{5}, & 3
\end{pmatrix}
\ ,\ 
\mbf{P}_{111} = 
\begin{pmatrix}
1, & \frac{11}{20}, & 0, & \frac{9}{4}
\end{pmatrix}
\ ,
\end{align*}
and $w_{ijk} = 1$ for every $0\leq i,j,k \leq 1$. 
Since the four boundary $u$-lines, i$.$e$.$ $u_{ij} = \ovl{\mbf{P}_{ij0}\mbf{P}_{ij1}}$ for each $0\leq i,j \leq 1$, meet at the point 
$\mbf{A} = 
\setlength\arraycolsep{1pt}
\begin{pmatrix}
1, & 0, & 0, & 5
\end{pmatrix}
$
it follows that $\phi$ is pyramidal. 
In particular, we compute (recall \cref{notation: pyramidal})
\begin{gather*}
\Delta_{000} = \frac{5}{6} \ ,\ 
\Delta_{100} = \frac{20}{21} \ ,\  
\Delta_{010} = \frac{80}{63} \ ,\  
\Delta_{110} = \frac{5}{3} \ ,\\[6pt]   
\Delta_{001} = \frac{40}{33} \ ,\ 
\Delta_{101} = \frac{15}{7} \ ,\ 
\Delta_{011} = \frac{20}{7} \ ,\  
\Delta_{111} = \frac{80}{33} \ . 
\end{gather*}
Thus, the tensor 
$$
W 
= \left( \frac{w_{ijk}}{\Delta_{ijk}}\right)_{0\leq i,j,k\leq 1}
= \left( \frac{1}{\Delta_{ijk}}\right)_{0\leq i,j,k\leq 1}
$$
does not have rank one, and by  \cref{theorem: tensor pyramidal} $\phi$ is not birational. 
However, we can render $\phi$ birational by computing new weights using the formulas in \cref{corollary: weight formulas pyramidal} for any choice of $(\alpha_0:\alpha_1)\times (\beta_0:\beta_1)\times (\gamma_0:\gamma_1) \in (\P_\R^1)^3$. 
Nevertheless, the new birational map $\phi$ might differ significantly from the original $\phi$ if we make a ``bad'' choice. 
A smarter idea is to compute a rank-one CP decomposition of $W$. 
A rank-one approximation of $W$ is given by 
$$
W_{\text{bir}} = 
\left(
\alpha_0 \, ,\, \alpha_1
\right)
\otimes
\left(
\beta_0 \, ,\, \beta_1
\right)
\otimes
\left(
\gamma_0 \, ,\, \gamma_1
\right)
=
\left( 
0.95 \, ,\, 0.91
\right)
\otimes
\left( 
1.06 \, ,\, 0.78
\right)
\otimes
\left( 
1.08 \, ,\, 0.75
\right)
\ .
$$
Specifically, this leads to the exact rational weights
$
w_{ijk} = \alpha_i \, \beta_j \, \gamma_k \, \Delta_{ijk}
$
for each $0 \leq i,j,k \leq 1$. 
Additionally, we compute  
$$
\distbir(\phi) = 
\frac{\lVert W - W_\text{bir} \rVert}{\lVert W \rVert} 
\sim 
0.2594
\ .
$$
In \cref{fig: birational approx}, we present a comparison between the deformations resulting from the original rational map, with uniform weights $w_{ijk} = 1$ for every $0\leq i,j,k \leq 1$, and its  birational approximation, utilizing the new weights. 
