\section{Results}\label{sec:wronskian}
\subsection{Identifiability for generic solutions}

We will prove that, unlike the ODE case, all of the identifiable functions of parameters can be read off from particular relations between the input and output variables called input-output equations. 
Below we recall some necessary notions and constructions from constructive differential algebra.

\begin{definition}[Differential rankings and characteristic sets]
\begin{enumerate}
\item[] 
 \item
  A {\em differential ranking} on $K\{x_1,\ldots,x_n\}$ is a total order $>$ on \[X := \{\partial_1^{n_1}\cdots\partial_n^{n_m}(x_j)\mid n_i\geqslant 0,\, 1\leqslant j\leqslant n\}\] satisfying:
  \begin{itemize}
    \item for all $x \in X$ and $\partial\in\Delta$, $\partial(x) > x$ and
    \item for all $x, y \in X$ and $\partial\in\Delta$, if $x >y$, then $\partial(x) > \partial(y)$.
  \end{itemize}
  It can be shown that a differential ranking on $K\{x_1,\ldots,x_n\}$ is always well-ordered.

\item
  For  $f \in K\{x_1,\ldots,x_n\} \backslash K$ and differential ranking $>$,
\begin{itemize}
    \item 
    $\lead(f)$ is the element of $X$ appearing in $f$ that is maximal with respect to $>$.
    \item 
    The \emph{leading coefficient} of $f$ considered as a polynomial in $\lead(f)$ is denoted by $\init(f)$ and called the \emph{initial} of $f$. 
    \item
    The \emph{separant} of $f$ is $\frac{\partial f}{\partial\lead(f)}$, the partial derivative of $f$ with respect to $\lead(f)$.
    \item 
    The \emph{rank} of $f$ is $\rank(f) = \lead(f)^{\deg_{\lead(f)}f}$.
    \item 
    For $S \subset K\{x_1,\ldots,x_n\} \backslash K$, the set of \emph{initials} and \emph{separants} of $S$ is denoted by $H_S$.
    \item 
    For $g \in K\{x_1,\ldots,x_n\} \backslash K$, say that $f < g$ if $\lead(f) < \lead(g)$ or $\lead(f) = \lead(g)$ and $\deg_{\lead(f)}f < \deg_{\lead(g)}g$.
\end{itemize}
    \item For $f, g \in K\{x_1,\ldots,x_n\} \backslash K$, $f$ is said to be reduced w.r.t. $g$ if no proper derivative of $\lead(g)$ appears in $f$ and $\deg_{\lead(g)}f <\deg_{\lead(g)}g$.
    \item 
    A subset $\mathcal{A}\subset K\{x_1,\ldots,x_n\} \backslash K$
    is called {\em autoreduced} if, for all $p \in \mathcal{A}$, $p$ is reduced w.r.t. every  element of $\mathcal A\setminus \{p\}$. 
    One can show that every autoreduced set is always finite.
    \item Let $\mathcal{A} = \{A_1, \ldots, A_r\}$ and $\mathcal{B} = \{B_1, \ldots, B_s\}$ be autoreduced sets such that $A_1 < \ldots < A_r$ and $B_1 < \ldots < B_s$. 
    We say that $\mathcal{A} < \mathcal{B}$ if
    \begin{itemize}
      \item $r > s$ and $\rank(A_i)=\rank(B_i)$, $1\leqslant i\leqslant s$, or
      \item there exists $q$ such that $\rank(A_q) <\rank(B_q)$ and, for all $i$, $1\leqslant i< q$, $\rank(A_i)=\rank(B_i)$.
    \end{itemize}
    \item An autoreduced subset of the smallest rank of a differential ideal $I\subset K\{x_1,\ldots,x_n\}$
    is called a {\em characteristic set} of $I$. One can show that every non-zero differential ideal in $K\{x_1,\ldots,x_n\}$ has a characteristic set. Note that a characteristic set does not necessarily generate the ideal.
    \item For elements $r_1,\ldots,r_n$ is a differential ring $(R,\Delta)$, the Wronskian matrix $\Wr(r_1,\ldots,r_n)$ with respect to a given $\partial\in \Delta$ is the matrix
    \[
    \begin{pmatrix}
    r_1 & \ldots&r_n\\
    \partial r_1 &\ldots &\partial r_n\\
    \vdots & \ddots &\vdots\\
    \partial^{n-1} r_1 &\ldots &\partial^{n-1} r_n\end{pmatrix}.
    \]
\end{enumerate}
\end{definition}

\begin{definition}[IO-equations]\label{def:IO-equations}
Given a differential ranking on the differential variables $\by$ and $\bw$, the \emph{IO-equations} are defined as the monic characteristic presentation of the prime differential ideal $I_\Sigma \cap \CC(\bk)\{\by,\bw\}$ with respect to this ranking  (see \cite[Definition~6 and Section~5.2]{Ovchinnikov-Identifiability2023} for more details). For each differential ranking, such a monic characteristic presentation is unique~\cite[Theorem~3]{Boulier2000}.
\end{definition}

Now we are ready to state the main result of this section, namely, that all the identifiable functions can be read off the coefficients of the IO-equations. 
Interestingly, the corresponding statement is not true for ODEs \cite[Example~2]{Ovchinnikov-Identifiability2023}.

\begin{theorem}\emph{(cf. \cite[Theorems 1 \& 2]{Ovchinnikov-Identifiability2023})}\label{thm:identifiability}
For a model $\Sigma$ of the form~\eqref{eq:sigma_def}, the identifiable functions in $\CC(\bk)$ form a subfield, and this subfield is generated by the coefficients of any set of IO-equations of the model.
\end{theorem}

\begin{remark}\label{rmk:injectivity}   
Note that using Theorem~\ref{thm:identifiability}, 
one obtains identifiability of the coefficients $C$ of the IO-equations $F_j(\bw,\by)$, $1\leqslant j\leqslant s$, considered as differential polynomials in $\bw,\by$. 
Elements of $C$ are in fact the generators of the field of identifiable functions. 
  For each parameter $k_i$ in $\bk$, one can check its identifiability by verifying whether $k_i \in  \mathbb{Q}(C)$. 
  This can be reduced to the ideal membership problem as described in~\cite[Section 1.3]{Rational} (for a randomized version, see~\cite[Theorem~3.3]{structidjl}).
  The {\sc Maple} code~\cite{allident_code} has been implemented in~\cite{Ovchinnikov-AllIdentifiable21} for testing this ideal membership.
\end{remark}

Before proving Theorem~\ref{thm:identifiability}, we will proceed with some preparation.
Consider a PDE model $\Sigma$ as in~\eqref{eq:sigma}, its prime differential ideal
$I_\Sigma$, and the corresponding field of fractions $\mathcal{F}$ (see Definition~\ref{def:generic_solution}). 
Since $I_\Sigma$ is stable under $\partial_t$ and $\partial_{x}$,
the derivations $\partial_t$ and $\partial_{x}$ can be transferred
to $\mathcal{F}$ in a natural way.
\begin{definition}We will call an element $c \in \mathcal{F}$ a \emph{constant}
if $\partial_t c=\partial_{x} c=0$. 
\end{definition}
The key difference with the ODE
case will be the following lemma.

\begin{lemma}\label{lem:const} 
If $c \in \mathcal{F}$ and $\partial_x(c) = 0$, then $c\in\CC(\bk)$. In particular, the set of constants of $\mathcal{F}$ is $\CC(\bk)$.
\end{lemma}
\begin{proof}
  Let $c=\frac{p}{q} \in \mathcal{F}$ be  such $\partial_x(c) = 0$,  $p, q \in R=\CC(\bk)\{\bv,\by,\bw\}$ are
  coprime and at least one of them does not belong to
  $\CC(\bk)$.
  There exists a positive integer $N$ such that,
  using equations~\eqref{eq:sigma} and their derivatives,
  we can replace $Q^Np$ and $Q^Nq$ by elements of
  $\CC(\bk) \{ \bw \}[\partial_x^i\bv,\ i\geqslant 0]$ equivalent to $Q^Np$ and $Q^Nq$ modulo $I_\Sigma$ and, thus, yielding
  the same element of $\mathcal{F}$. By~\eqref{eq:diff_ideal}, $\mathcal{F}$ has a subfield isomorphic to the field of rational functions
  \[\mathcal{F}_0:=\CC(\bk)\langle \bw \rangle(\partial_x^i\bv,\ i\geqslant 0),\] and $\frac{p}{q}$ belongs to this subfield. With
  respect to $\partial_{x}$, the field $\mathcal{F}_0$ is isomorphic to the field of
  differential rational functions over $\bk$ in infinitely many
  variables
  $\bv, \bw, \partial_t \bw, \partial_t^2
  \bw, \ldots$. Since the constants of a field of differential
  rational functions are exactly the constants of the ground field, we
  deduce that $\frac{p}{q} \in \CC(\bk)$.
\end{proof}

\begin{lemma}\label{lem:fieldofdef} Let $\Delta$ be a finite set of derivations, $L \subset K$  differential fields, and $X$ a finite set of variables. 
Let $P$ be a prime non-zero differential ideal of $K\{X\}$ such that the ideal generated by $P$ in $\overline{K}\{X\}$ is prime, where $\overline{K}$ is the algebraic closure of $K$. 
If $\mathcal{C}$ is a monic characteristic presentation of $P$, then the field of definition of $P$ over $L$ is the field extension of $L$ generated by the coefficients~of~$\mathcal{C}$.
\end{lemma}
\begin{proof}
Mutatis mutandis proof of \cite[Proposition~2]{Ovchinnikov-Identifiability2023}.
\end{proof}

\begin{corollary}[{cf. \cite[Corollary~1]{Ovchinnikov-Identifiability2023}}]\label{cor:generateIO}
If $\mathcal{C}$ is a monic characteristic presentation of the prime differential ideal $J := I_\Sigma \cap \mathbb{C}(\bk)\{\by,\bw\}$, then field of definition of $J$ over $\mathbb{C}$ is generated over $\mathbb{C}$ by the coefficients of $\mathcal{C}$. 
\end{corollary}
\begin{proof}
This follows from Lemma~\ref{lem:fieldofdef} because the differential ideal generated by $J$ in $\overline{\mathbb{C}(\bk)}\{\by,\bw\}$ is prime.
\end{proof}

\begin{lemma}[{cf. \cite[Lemma 1]{Ovchinnikov-Identifiability2023}}]\label{lem:support}
Consider a polynomial $P \in I_\Sigma \cap \CC(\bk)\{\by, \bw\}$ with at least one of the coefficients being one. If there is no element in  $I_\Sigma \cap \CC(\bk)\{ \by,\bw\}$ whose support is a subset of the support of $P$, then all coefficients of $P$ are identifiable.
\end{lemma}
\begin{proof}
We write $P=m_0+\sum_{i=1}^{\ell} c_i m_i$, where $m_0, \ldots, m_{\ell}$ are monomials in 
\[
\left\{\partial_t^{i} \partial_{x}^j \by, \partial_t^i \partial_{x}^j \bw \mid i, j \geqslant 0\right\}
\] 
and $c_1, \ldots, c_{\ell} \in \CC(\bk)$. 
    Let $(\hat\bv,\hat\by,\hat\bw)$ be the generic solution of $I_\Sigma$. 
    We consider the Wronskian \[W(\hat{\by}, \hat{\bw}):= \Wr(m_1(\hat{\by}, \hat{\bw}), \ldots, m_{\ell}(\hat{\by}, \hat{\bw}))\]  with respect to $\partial_{x}$. 
    If this Wronskian was singular, then, by \cite[Theorem~3.7]{Kaplansky},
    there would exist $a_1, \ldots, a_{\ell} \in F$ constant with   respect to $\partial_{x}$ so that \[a_1 m_1(\hat{\by}, \hat{\bw})+\ldots+a_{\ell} m_{\ell}(\hat{\by}, \hat{\bw})=0.\] By Lemma~\ref{lem:const},  $a_1, \ldots, a_{\ell} \in \CC(\bk)$. 
    This yields a nonzero element \[a_1 m_1+\ldots+a_{\ell} m_{\ell} \in I_\Sigma\] with the support being a  subset of the support of $P$.
    Thus, $W$ is nonsingular. 
    By taking the derivatives of $P(\hat{\by}, \hat{\bw})=0$ of orders from $0$ to $\ell - 1$ with respect to $\partial_x$, we obtain: 
    $$
    \left(\begin{array}{c}
        m_0(\hat{\by}, \hat{\bw}) \\
        \partial_{x} m_0(\hat{\by}, \hat{\bw}) \\
        \vdots \\
        \partial_{x}^{\ell-1} m_0(\hat{\by}, \hat{\bw})
      \end{array}\right)
    =W(\hat{\by}, \hat{\bw}) 
    \left(\begin{array}{c}
    c_1 \\
    c_2 \\
    \vdots \\
    c_{\ell}
    \end{array}\right).
    $$ 
    Viewing this as a nonsingular linear system in $c_1, \ldots, c_{\ell}$ over $\CC\langle\hat{\by},  \hat{\bw}\rangle$ and applying Cramer's rule, we deduce that each of $c_1, \ldots, c_{\ell}$ belongs to $\CC\langle\hat{\by}, \hat{\bw} \rangle$.
\end{proof}

\begin{corollary}\label{cor:identifiability}
  If system~\eqref{eq:sigma} is of the form
  \[
  \Sigma =
  \begin{cases}
    \partial_t \bv=\bff\left(\bk, \bw, \bv, \partial_{x} \bv, \ldots, \partial_{x}^h \bv\right) \\
    \by=\bv,
  \end{cases}
  \]
  that is, all  states are observable, then all  coefficients of
  $\bff$ as polynomials in
  $\bw, \bv, \partial_{x} \bv, \ldots, \partial_{x}^h \bv$ are
  identifiable.
\end{corollary}

\begin{proof} It is sufficient to prove that polynomials
  $\partial_t \bv-\bff$ satisfy the condition of Lemma~\ref{lem:support}. Assume that one of them, say
  $\partial_t v_1-f_1$ does not. 
  Therefore, there is a polynomial
  $g \in I_\Sigma$ with the support being a proper subset of the support of
  $\partial_t v_1-f_1$. 
  By cancelling $\partial_t v_1$, we obtain a
  $\CC(\bk)$-linear combination $\tilde{g}$ of $\partial_t v_1-f_1$
  and $g$ with the support being a subset of the support of
  $f_1$. Then $\tilde{g}$ is a nonzero element of
  $I \cap \CC(\bk) \{ \bw \}[\partial_x^i\bv,\ i\geqslant 0]$, contradicting
  \eqref{eq:diff_ideal}.
\end{proof}



We are now ready to prove our main result, Theorem~\ref{thm:identifiability}.

\begin{proof}[Proof of Theorem~\ref{thm:identifiability}]
Let 
\[S =\{c \in \CC(\bk)\mid c \text{ is identifiable}\}= \CC(\bk)\cap\CC\langle \hat{\by},\hat{\bw}\rangle,\]
and so $S$ is a subfield in $\CC(\bk)$. Let $\mathcal{C}$ be a set of IO-equations of $\Sigma$ and $C$  the set of coefficients of $\mathcal{C}$. We will prove that $S = \CC(C)$.

We first show that $S \subset \CC(C)$.
    For this, let $c \in \CC(\bk)$ be identifiable.
    We will show how the proof of~\cite[Theorem 1]{Ovchinnikov-Identifiability2023} extends to PDEs to prove that $c \in \CC(C)$. By Corollary~\ref{cor:generateIO}, the field of definition of $I_\Sigma\cap\CC(\bk)\{\by,\bw\}$ is equal to $\CC(C)$. In particular, $I_\Sigma\cap\CC(\bk)\{\by,\bw\}$ is generated over $\CC(\bk)$ by $I_\Sigma\cap\CC(C)\{\by,\bw\}$.

    Since $c \in \CC\langle \hat{\by},\hat{\bw}\rangle$, 
     there exist $g \in \CC\{\by,\bw\}\setminus I_\Sigma$ and $h \in \CC\{\by,\bw\}$ such that $gc + h \in I_\Sigma$. Therefore, there exist $m_1,\ldots,m_r \in \CC(\bk)\{\by,\bw\}$ and $p_1,\ldots,p_r \in I_\Sigma \cap \CC(C)\{\by,\bw\}$ such that   
     \[
     gc+h = m_1p_1+\ldots+m_rp_r.
     \] 
     Now assume that $c \not\in \CC(C)$. By \cite[Theorem 9.29, p. 117]{milneFT}, there exists an automorphism $\sigma$ on $\overline{\CC(\bk)}$ that fixes $\CC(C)$ pointwise, but does not fix $c$, i.e., $\sigma(c) \neq c$.   Extend $\sigma$ to $\overline{\CC(\bk)}\{\bv,\by,\bw\}$ by letting $\sigma$ fix $\bv ,\by$, and $\bw$.  We have in $\overline{\CC(\bk)}\{\bv,\by,\bw\}$ that
    \begin{equation}
    \label{eq:quot2}
    \begin{aligned}
        \left(gc+h\right) - \sigma(gc+h) & = \left( m_1p_1+\ldots+m_rp_r \right) - \sigma(m_1p_1+\ldots+m_rp_r) \\
        g(c-\sigma(c)) & = (m_1-\sigma(m_1))p_1+\ldots+(m_r-\sigma(m_r))p_r.
    \end{aligned}  
    \end{equation}
    Let $\overline{I_\Sigma }$ denote the differential ideal generated by $I_\Sigma$ in $\overline{\CC(\bk)}\{\bv,\by,\bw\}$. Since $\overline{I_\Sigma }$ is a prime differential ideal and the right-hand side of \eqref{eq:quot2} belongs to $\overline{I_\Sigma }$, it follows that either $g \in \overline{I_\Sigma }$ or $c-\sigma(c) \in \overline{I_\Sigma }$.  As $\sigma(c) \ne c$, we have that $c-\sigma(c)$ is a non-zero element of $\overline{\CC(\bk)}$. Since $\overline{I_\Sigma }$ is a proper ideal, therefore $c-\sigma(c) \not\in \overline{I_\Sigma }$.  Therefore, $g \in \overline{I_\Sigma }$.  Hence, \[g \in \overline{I_\Sigma } \cap \CC(\bk)\{\bv,\by,\bw\} = I_\Sigma,\] contradicting the assumption on $g \not\in I_\Sigma$.

     For the proof of the converse, note that we have shown in Lemma~\ref{lem:const} that the set of constants of $\mathcal{F}$ coincides with $\CC(\bk)$. Therefore, the assumption of  \cite[Theorem~2]{Ovchinnikov-Identifiability2023} holds. So we follow the proof of~\cite[Theorem~2]{Ovchinnikov-Identifiability2023} for PDEs.

    Let $J := I_\Sigma \cap \CC(\bk) \{\by, \bw\}$.  Let         $\mathcal{B}$ be the set of differential monomials in $\by$ and $\bw$ indexed by $\mathbb{N}$ such that the indexing respects a ranking. Then $\mathcal{B}$ is a basis for $\CC(\bk)\{\by,\bw\}$ as a vector space over $\CC(\bk)$. 
    Consider a basis $\mathcal{B}_J$ for $J$, as a $\CC(\bk)$-subspace of $\CC(\bk)\{\by,\bw\}$. Each element of $\mathcal{B}_J$ is a finite linear combination of the element of $\mathcal{B}$. 
    Autoreduce $\mathcal{B}_J$ as a set of vectors expressed in the basis $\mathcal{B}$ and call it $\mathcal{B}_J'$. 
    Note that $\mathcal{B}_J'$ is still a basis of $J$ as a vector space. 
    The field of definition of $J$ over $\CC$ is contained in the field generated by the coefficient of $\mathcal{B}_J'$ written as linear combinations of $\mathcal{B}$. 
    Therefore, it is sufficient to prove that these coefficients are identifiable.

    Let $P \in J$ be the differential polynomial corresponding to a member of $\mathcal{B}_J'$ of $J$. 
    Let $q$ be a polynomial whose support is a subset of $P$ and whose monomials are linearly dependent modulo $J$ over $\CC(\bk)$. The representation of  $q$ in basis $\mathcal{B}$ can be reduced to zero by $\mathcal{B}_J$, however, $q$ cannot be reduced to zero by $P$. Also, $q$ reduced by $P$ cannot be further reduced by other elements of $\mathcal{B}_J'$, as $\mathcal{B}_J'$ is a reduced basis. This proves that there is no $q$ whose support is a subset of the support of $P$ and whose support is linearly dependent. Therefore, by Lemma~\ref{lem:support}, the coefficients of $P$ are identifiable.   
\end{proof}


\subsection{Identifiability for solutions with specified initial and boundary conditions}
In this section, we are in the setup of Definition~\ref{def:idinbc}.
Consider a PDE system of the form~\eqref{eq:PDEarb} and each $\mathcal{C}_i$  contained in the $C^\infty$-functions on a domain $\mathcal{D}$. 
Fix a differential ranking such that any derivative of $\bv$ is greater than any derivative of~$\by$, and let
\begin{equation}\label{eq:dec}
I_\Sigma = [C_1]:H_{C_1}^\infty\cap\ldots\cap [C_r]:H_{C_r}^\infty
\end{equation}
be a decomposition computed by~\cite[Section~4]{Boulier2000} or~\cite[Algorithm~7.2]{Hubert2} with respect to the differential ranking. 
For each $i$, $1\leqslant i\leqslant r$, let \[\widetilde{C_i} = C_i\cap \mathbb{C}(\bk)\{\by\}.\]
If the system~$\Sigma$ is as in~\eqref{eq:sigma}, then, as we discussed, $I_\Sigma$ is a prime differential ideal and, as a result, one can remove redundant components in~\eqref{eq:dec} and obtain $r = 1$ and $\widetilde{C_1} \subset C_1 \subset I_\Sigma$, see \cite[Theorem~3.2.1]{KR}. If $\Sigma$ is more general and $I_\Sigma$ is not necessarily a prime differential ideal, consider the set $\widetilde{C} = \prod_{i=1}^r \widetilde{C_i} \subset I_\Sigma$.
By dividing every element of $\widetilde{C}$ by an element of $\mathbb{C}(\bk)$, for every $c \in \widetilde{C}$,
we pick a representation of the form
\begin{equation}\label{eq:grouping}
c = p_{0,c} + \sum_{j=1}^{q_c}a_{j,c}\cdot p_{j,c},
\end{equation}
where $p_0,\ldots,p_{q_c} \in \mathbb{C}\{\by\}$ and $a_1\ldots,a_{q_c} \in \mathbb{C}(\bk)$. Denote
$\Wr_c = \Wr(p_{1,c},\ldots, p_{q_c,c})$.
\begin{remark}\label{rem:grouping}
Such a grouping~\eqref{eq:grouping} is implemented in {\sc Maple} in~\cite{allident_code}, the function {\tt DecomposePolynomial}.
\end{remark}



\begin{proposition}
\label{prop:identicbc}
Let $c \in \widetilde{C}$, defined above. If, for all  
 $\widehat{\bk} \in \Omega$ and
 solutions  $(\widehat{\bv},\widehat{\by})$ of~\eqref{eq:PDEarb} with the parameter values $\widehat{\bk}$,
there exists a point $(t_0,x_0) \in \mathcal{D}$ such that the matrix  $\Wr_c\left(\widehat{\by}\right)(t_0,x_0)$ with respect to $\partial_x$ or $\partial_t$ is invertible, then 
\begin{itemize}\item
all $a_{1,c},\ldots,a_{q_c,c}$ are identifiable.\item Moreover, let $k_{i_1},\ldots, k_{i_c}$ be the parameters that explicitly appear in $a_{1,c},\ldots,a_{q_c,c}$. If the ``coefficient map''
\[\varphi_c: (k_{i_1},\ldots, k_{i_c})\mapsto (a_{1,c},\ldots,a_{q_c,c})\] is injective, then the parameters $k_{i_1},\ldots, k_{i_c}$ are identifiable.
\end{itemize}
\end{proposition} 
\begin{proof}
Suppose that there exists $j$ such that $a_{j,c}$ is not identifiable according to Definition~\ref{def:idinbc}. Let $\widehat{\bk}_1, \widehat{\bk}_2 \in \Omega$ and solutions $(\widehat{\bv}_1,\widehat{\by}_1)$ and  $(\widehat{\bv}_2,\widehat{\by}_2)$ of~\eqref{eq:PDEarb}  be such that
\begin{equation}
\label{eq:nonident}
\widehat{\by}_1 = \widehat{\by}_2\quad \text{but}\quad a_{j,c}(\widehat{\bk}_1)\ne a_{j,c}(\widehat{\bk}_2).
\end{equation}
Consider the square system of linear equations
\begin{equation}\label{eq:Wraj}
\begin{cases}
\sum\limits_{j=1}^{q_c}a_{j,c}\cdot p_{j,c} =-p_{0,c} \\
\sum\limits_{j=1}^{q_c}a_{j,c}\cdot \partial(p_{j,c}) =-\partial(p_{0,c})\\
\qquad\vdots\\
\sum\limits_{j=1}^{q_c}a_{j,c}\cdot \partial^{q_c-1}(p_{j,c}) =-\partial^{q_c-1}(p_{0,c})
\end{cases}
\end{equation}
in the unknowns $a_{1,c},\ldots,a_{q_c,c}$, whose matrix is $\Wr_c(\by)$. Assume that, for all $\widetilde{\bk} \in \Omega$ and solutions $(\widetilde{\bv},\widetilde{\by})$ of~\eqref{eq:PDEarb} with parameters $\widetilde{\bk}$, there exists $(t_0,x_0) \in \mathcal{D}$ such that  the matrix  $\Wr_c\left(\widetilde{\by}\right)(t_0,x_0)$ with respect to $\partial_x$ ($\partial_t$ is considered similarly) is invertible. Substituting $\widehat{\by}_1$ or $\widehat{\by}_2$ and the corresponding point $(t_0,x_0)$  into~\eqref{eq:Wraj} and solving returns $\left(a_{1,c}(\widehat{\bk}_1),\ldots,a_{q_c,c}(\widehat{\bk}_1)\right)$ or $\left(a_{1,c}(\widehat{\bk}_2),\ldots,a_{q_c,c}(\widehat{\bk}_2)\right)$, respectively. By the first part of~\eqref{eq:nonident}, these tuples are equal, which contradicts with the second part of~\eqref{eq:nonident}.

For the proof of the second item, suppose that the coefficient map $\varphi_c$ is injective. If $k_{i_j}$ is not identifiable, then there exist $\widehat{\bk}_1, \widehat{\bk}_2 \in \Omega$ and solutions $(\widehat{\bv}_1,\widehat{\by}_1)$ and $(\widehat{\bv}_2,\widehat{\by}_2)$ of~\eqref{eq:PDEarb} with  parameter values $\widehat{\bk}_1$ and $\widehat{\bk}_2$ such that
\[
\widehat{\by}_1 = \widehat{\by}_2\quad \text{but}\quad \proj_{k_{i_j}}(\widehat{\bk}_1)\ne \proj_{k_{i_j}}(\widehat{\bk}_2).
\]
Hence, by the injectivity of $\varphi_c$, there exists $\ell$ such that $a_{\ell,c}(\widehat{\bk}_1)\ne a_{\ell,c}(\widehat{\bk}_2)$, which contradicts the identifiability of $a_{\ell,c}$ established above.
\end{proof}

