\section{Algorithms}\label{sec:algorithm}

The correctness of Algorithms~\ref{alg:algebraic} and~\ref{alg:strong}, which we present in this section, follows from Theorem~\ref{thm:identifiability} and Proposition~\ref{prop:identicbc}, respectively.

\begin{algorithm}[!h]
\caption{Assessing identifiability in the sense of Defintion~\ref{def:identifiability}}\label{alg:algebraic}
\begin{description}
    \item[Input] A rational PDE system of the form
    \[
    \begin{cases}
      \partial_t{\bv}=\bff \left( \bk, \bw, \bv, \partial_{x}{\bv}, \ldots, \partial_{x}^h \bv \right) \\
      \by=\bg\left( \bk, \bw, \bv, \partial_{x}{\bv}, \ldots, \partial_{x}^h \bv\right).
    \end{cases}
    \]

    \item[Output] A list of generators of the field of identifiable functions of the system and, for each parameter, $k_i$ whether it is identifiable or not.
\end{description}

\begin{enumerate}[label = \textbf{(Step~\arabic*)}, leftmargin=*, align=left, labelsep=2pt, itemsep=0pt]
    \item Using
  \texttt{RosenfeldGroebner} with an elimination ranking $\bv > \by,\bw$,  eliminate the variables $\bv$ and obtain a set $\mathcal{S}$ of IO-equations of the input PDE system.
  \item Let $\mathcal{C} \subset \mathbb{C}(\bk)$ be the set of the coefficients of $\mathcal{S}$.
  \item \textbf{Return}:
  \begin{itemize}
      \item For the generators of the field of identifiable functions, the set $\mathcal{S}$. It can be additionally simplified using~\cite{allident_code} by applying {\tt FieldToIdeal} and then {\tt FilterGenerators} (or~\cite[Section~5]{Meshkat2009});
      \item For each $k_i \in \bk$, the result of the test $k_i \in \mathbb{C}(\bk)$ (using, e.g., \cite[Section 1.3]{Rational}, see~\cite{allident_code} for implementation).
  \end{itemize}
\end{enumerate}
\end{algorithm}

\begin{algorithm}[!h]
\caption{Approach to establishing strong identifiability  (Defintion~\ref{def:idinbc})}\label{alg:strong}
\begin{description}
    \item[Input] 
    A system of rational PDEs of the form
    \[
    \mathbf{F}\left(\bk, \bv\right) = 0, \quad \mathbf{y} = \mathbf{G}(\bk, \bv).
    \]
    together with some set of requirements $\mathcal{R}$ (regularity, boundary conditions, etc.) on the states $\bv$ and a domain $\Omega$ for the parameter values.

    \item[Output] For each parameter $k_i$, either returns that it is strongly identifiable, or that the test was inconclusive.
\end{description}

\begin{enumerate}[label = \textbf{(Step~\arabic*)}, leftmargin=*, align=left, labelsep=2pt, itemsep=0pt]
    \item Using
  \texttt{RosenfeldGroebner} with an elimination ranking $\bv > \by$,  eliminate the variables $\bv$, and obtain a set $\mathcal{S} = \{S_1, \ldots, S_\ell\}$ of IO-equations of the input PDE system.
  We denote the set of their coefficients by $\mathcal{C}$.
  \item For each $j$, $1 \leqslant j\leqslant \ell$, write $S_j$ in the form 
  \[
    F_j = p_{0,j} + \sum_{i=1}^{L_j}a_{i, j}\cdot p_{i, j},
  \]
  with $a_{i, j} \in \mathbb{C}(\bk)$ and $p_{i, j} \in \mathbb{C}\{\by\}$ (see Remark~\ref{rem:grouping}).
  Compute the Wronskians $\operatorname{Wr}_{j,x}$ and $\operatorname{Wr}_{j,t}$ of $p_{1, j}, \ldots, p_{L_j, j}$ with respect to $\partial_x$ and $\partial_t$, respectively.
  \item For each $j$, $1 \leqslant j\leqslant \ell$,
compute the normal forms $N_{j,x}$ and  $N_{j,t}$  of $\operatorname{Wr}_{j,x}$ and  $\operatorname{Wr}_{j,t}$, respectively, w.r.t. the input PDE system,
and obtain a sufficient condition 
  $\mathcal{I} = \bigwedge_j(N_{j,x}\ne 0 \lor N_{j,t}\ne 0)$ for the identifiability of $\mathcal{C}$.
  \item Check if $\mathcal{I}$ holds under the requirements $\mathcal{R}$ and for the parameters in $\Omega$\footnote{Since there are almost no assumptions on the requirements, this step is non-algorithmic. We show, how to do this in practice in the next section.}.
  \item If $\mathcal{I}$ does not hold, \textbf{return} ``inconclusive'' for every parameter.
  \item If $\mathcal{I}$ does hold, \textbf{return} ``identifiable'' for every parameter $k_i$ such that $k_i \in \mathbb{C}(\bk)$ (can be checked with, e.g., \cite[Section 1.3]{Rational}, see~\cite{allident_code} for implementation), and ``inconclusive'' for the rest of the parameters.
\end{enumerate}
\end{algorithm}

\section{Examples of PDE identifiability}\label{sec:computations}

In this section, we consider several models arising in mathematical biology (Section~\ref{subsec:math-bio-pde}), as well as other natural phenomena (Section~\ref{subsec:applied-maths-pdes}). We use Proposition~\ref{prop:identicbc} and Algorithm~\ref{alg:strong},  to test the identifiability of the parameters in these models. 
% -------------------------------------------------------------------------
\subsection{PDEs arising in mathematical biology}\label{subsec:math-bio-pde}
We study four well-known, and increasingly complex, PDE systems in mathematical biology \cite{murray-book1}. 
All of these examples use parabolic PDEs.
% -------------------------------------------------------------------------
\begin{example}[Scalar Reaction--Diffusion Equation]\label{subsubsec:nutrient}

We start by considering the following reaction--diffusion equation in which $c$ represents the concentration of a diffusible nutrient, such as oxygen or glucose, which is consumed at a rate which is an increasing, saturating function of its concentration~\cite{murray-book1}:
\begin{equation}\label{eq:nutrient}
  \partial_tc(x,t) =d\partial_x^2 c(x,t) +\frac{\lambda c(x,t)}{c_0+c(x,t)},
\end{equation}
where the set of parameters is $\{d, c_0, \lambda\}$, and the boundary
conditions are given by:
\begin{align}
  \partial_x c(x,t)(0,t) = & 0 \label{eq:nutrient-bc1}\\
  c(R,t) = & 1 \label{eq:nutrient-bc2}\\
  c(x,0) = & 1, \quad 0 \leq x \leq R. \label{eq:nutrient-bc3}
\end{align}

Following Definition~\ref{def:idinbc}, our field is $\mathbb{K} = \RR$ and $\Omega = \RR_+^3$.
We follow Algorithm~\ref{alg:strong}  to check
the identifiability of the parameters of~\eqref{eq:nutrient}. Details of
the computations can be found in the {\sc Maple} worksheet \texttt{nutrient.mpl}\footnote{\url{https://github.com/rahkooy/PDE-Identifiability}}.

Considering the numerator of the rational  function~\eqref{eq:nutrient}, 
i.e., the differential polynomial 
\begin{equation}\label{eq:nutrient-in-out}
    -d c(x,t)\partial_x^2 c(x,t) -d c_0\partial_x^2c(x,t)+ 
    c(x,t)\partial_tc(x,t) + c_0 \partial_t c(x,t) - \lambda c(x,t),
\end{equation}
we collect four monomials of~\eqref{eq:nutrient-in-out}
whose coefficient (with respect to the elements in $\CC(d,c_0,\lambda)$) is not 1, and compute $W$,  the determinant of their Wronskian to check if it is nonsingular. 
To do so, we compute the normal form of $W$ (using Rosenfeld-Gr\"obner),
and check when its coefficients are zero.

Note that if we obtain nonsingularity of the Wronskian from a subset of the coefficient, it implies that the Wronskian is nonsingular. The first ten coefficients are zero if and only if 
\begin{equation}
    \partial_tc(x,t) = 0 \quad \text{or} \quad \partial_x c(x,t)=0.
\end{equation}

So we investigate the following two cases. 

\paragraph{Case 1. $\partial_tc(x,t)=0$}
In this case, the function $c$ does not depend on $t$ anymore, and therefore,  $c(x,t)=c(x)$. Using the boundary conditions~\eqref{eq:nutrient-bc2} and~\eqref{eq:nutrient-bc3}, 
we obtain $c(x)=1$, a constant  function. On the other hand, 
considering $\partial_tc(x,t)=0$, the differential polynomial ~\eqref{eq:nutrient-in-out} will be simplified to the following 
polynomial (which is the LHS of  ODE, rather than the original PDE):
  \begin{equation}\label{eq:nutrient-odex}
    -d c(x)\partial_x^2 c(x) -d c_0\partial_x^2c(x) - \lambda c(x).
  \end{equation}

Substituting $c(x)=1$  into~\eqref{eq:nutrient-odex}, we obtain
$- \lambda$, which is not zero, as the parameters are assumed to be positive. So this case cannot happen.

\paragraph{Case 2. $\partial_xc(x,t)=0$}
This condition means that $c$ does not depend on $x$, hence, $c(x,t)=c(t)$. So substituting this condition into the PDE~\eqref{eq:nutrient}, we obtain the following ODE:
  \begin{equation}\label{eq:nutrient-odet}
    \partial_tc(t) = \frac{ \lambda c(t)}{c_0+c(t)}.
  \end{equation}
Using boundary condition~\eqref{eq:nutrient-bc2}, i.e., $c(R,t)=1$,
we obtain $\partial_t c(t) =0$. Therefore
ODE~\eqref{eq:nutrient-odet} is equal to zero if and only if
\begin{equation}
\frac{ \lambda c(t)}{c_0+c(t)} = \frac{ \lambda}{c_0+1}=0,
\end{equation}
which can happen only if $\lambda =0$. This is impossible according
to our assumption on the positivity of the parameters, i.e., $\Omega = \RR_+^3$.  So Case 2
neither can happen.

In conclusion, none of the cases considered above can happen. This means
that the Wronskian matrix is non-singular. So, by Proposition~\ref{prop:identicbc}, the coefficients of the
PDE~\eqref{eq:nutrient-in-out}, i.e., $\{d, d c_0, c_0, \lambda\}$,
are all identifiable. 
\end{example}  
%-------------------------------------------------------------------------
\begin{example}[Fisher's Equation]
Next, we consider
Fisher's equation that describes the diffusive spread of a species which undergoes logistic growth~\cite{murray-book1}. 
Fisher's equation is given by the following PDE:
\begin{equation}\label{eq:fisher}
  \partial_tn(x,t) = d \partial_x^2 n(x,t) + r
  n(x,t)\left(1-\frac{n(x,t)}{k} \right),
\end{equation}
where $n(x,t)$ is the input function, $x,t$  are the variables, and
$d, r, k$ are the parameters. The boundary conditions are given by

\begin{equation}\label{eq:fisher-bc}
  n(x,t)  \to 
            \begin{cases}
              k, \quad x \to -\infty \\
              0, \quad x \to \infty,
            \end{cases} 
\end{equation}
and the initial condition is given by prescribed $u(x,0)$ as follows, which is compatible with the boundary  conditions~\eqref{eq:fisher-bc}.
\begin{equation}\label{eq:fisher-ic}
  n(x,0)  = n_0(x)  = \frac{ke^{-\alpha x}}{1+e^{-\alpha x}}.
\end{equation}

Following Definition~\ref{def:idinbc}, our field is $\mathbb{K} = \RR$ and $\Omega = \RR_+^3$.
Below we follow Algorithm~\ref{alg:strong} for checking the identifiability of the parameters. Details of the computations can be found in the {\sc Maple} worksheet \texttt{fisher.mpl}\footnote{\url{https://github.com/rahkooy/PDE-Identifiability}}.
Simplifying~\eqref{eq:fisher}, we obtain
  \begin{equation}\label{eq:fisher-simple}
  \partial_tn(x,t) - d \partial_x^2 n(x,t) - rn(x,t) + \frac{rn(x,t)^2}{k},
\end{equation}
from which we collect all of the monomials, except for $\partial_tn(x,t)$   whose coefficient is $1$, and compute $W$, the determinant of their Wronskian. 
%
    Using Rosenfeld-Gr\"obner, we compute the normal form of the determinant of $W$, which is a rational function. We would like to check if this rational function is identically zero. Equivalently, we would like to check if the numerator of this rational function, say $N$, is zero. For this, we consider the coefficients of $N$ as a polynomial in terms of parameters. There are four such coefficients (which are differential polynomials in terms of variables $x$ and $t$). 

Computing the coefficients of the normal form of $W$, one can see that the coefficients are zero if and only if 
\begin{equation}\label{eq:fisher-coeff-rg}
    \partial_xn(x,t)=0 \quad \text{or} \quad \partial_tn(x,t)=0,
\end{equation}
which leads to the following cases.

\paragraph{Case 1. $\partial_xn(x,t)=0$.}
In this case, the function $n(x,t)$ does not depend on $x$, hence  $n(x,t)=n(t)$. However, the initial condition~\eqref{eq:fisher-ic}   implies that $n$ is a function of $x$ unless $\alpha=0$, which cannot happen as the parameters are supposed to be positive.

\paragraph{Case 2. $\partial_tn(x,t)=0$.}
This case implies that $n$ does not depend on $t$, hence, $n(x,t)=n(x)$. From the initial condition~\eqref{eq:fisher-ic}, we have that 
\begin{equation}\label{eq:fisher-nx}
    n(x) = n_0(x) = \frac{k e^{-\alpha x}}{1 + e^{-\alpha x}}.
\end{equation}

We substitute $\partial_tn(x,t)=0$ into Fisher's Equation~\eqref{eq:fisher} to obtain the following ODE:
\begin{equation}\label{eq:fisher-odet}
    -d \partial_x^2 n(x) - rn(x) + \frac{rn(x)^2}{k} = 0.
\end{equation}
Equation~\eqref{eq:fisher-nx} must satisfy ODE~\eqref{eq:fisher-odet}. Evaluating the ODE at $n(x)$, we obtain
\begin{equation}\label{eq:fisher-evalnx}
    \frac{\left((\alpha^2d - r)e^{-\alpha x} - \alpha^2d -
        r\right)ke^{-\alpha x}}{\left(1 + e^{-\alpha x}\right)^3}.
\end{equation}
Equation~\eqref{eq:fisher-evalnx} is zero if and only if its numerator is zero, which is the case if and only if either $k=0$ (which is not  possible according to our assumption that parameters are positive), or
\begin{equation}
    (\alpha^2d-r) e^{-\alpha x}-\alpha^2 d-r =0.
\end{equation}
The above equation can happen only if the coefficient of the exponential term, as well as the constant term are zero. This leads to the equations
\begin{align}
    \alpha^2 d-r &=0 \\
    -\alpha^2 d-r & = 0,
\end{align}
which leads to $2 \alpha^2d=0$. But this cannot happen as $\alpha$  and $d$ are assumed to be non-zero.

So from the above discussions, we conclude that none of the above two cases can happen, hence, the coefficients of the Fisher  equation~\eqref{eq:fisher}, that is, by Proposition~\ref{prop:identicbc}, these functions of parameters are identifiable: $d$, $\frac{r}{k}$ and $\frac{1}{k}$. By the second part of Proposition~\ref{prop:identicbc}, the parameters $d,r,k$ are identifiable.
\end{example}

