\subparagraph{Rooted graphs.} A rooted graph is a graph where some vertices are labeled---formally:
%. A formal definition is as follows. 

\begin{definition}[Rooted graphs]\label{def:boundariedGraph}
A {\em rooted graph} is a graph $G$ with a set $\partial(G)\subseteq V(G)$ of distinguished vertices
 called {\em roots} and a labeling $\lambda_G: \partial(G)\rightarrow \mathbb{N}$. 
The set $\partial(G)$ is the {\em root set} of $G$, and the {\em label set} of $G$ is $\Lambda(G)=\{\lambda_{G}(v)\mid v\in \partial(G)\}$.
\end{definition}

\begin{definition}[{Topological minors of rooted graphs~\cite{GroheKMW11}}]
Let $G$ and $H$ be two rooted graphs with labelings $\lambda_H$ and $\lambda_G$ for their root sets.  We say that $H$ is a {\em topological minor} of $G$ if there exist injective functions $\phi: V(H)\rightarrow V(G)$ and $\varphi: E(H)\rightarrow {\sf paths}(G)$ such that 
\begin{itemize}
\setlength\itemsep{0em}
\item for every $e=\{h,h'\}\in E(H)$, the endpoints of $\varphi(e)$ are $\phi(h)$ and $\phi(h')$,
\item for every distinct $e,e'\in E(H)$, the paths $\varphi(e)$ and $\varphi(e')$ are internally vertex-disjoint,
\item there does not exist a vertex $v$ in the image of $\phi$ and an edge $e\in E(H)$ such that $v$ is an internal vertex on $\varphi(e)$, and
\item for every $v\in \partial(H)$, $\lambda_H(v) = \lambda_G(\phi(v))$.
\end{itemize}
We say that $(\phi,\varphi)$ is a {\em realization} of $H$ as a topological minor in $G$. Moreover, the subgraph of $G$ induced by the union of the edges in the paths in $\varphi(e)$ for $e\in E(H)$ and the vertices in $\phi(h)$ for $h\in V(H)$ is called a {\em topological minor model} of $H$. 
\end{definition}
Note that if $\partial(G)=\emptyset$, then the above coincides with the usual definition of topological minors.  
%the definition above coincides with the standard definition of a topological minor.  



\begin{proposition}{\rm (\cite{GroheKMW11})}\label{prop:TMcontainment}
	There is
	 an algorithm that, given two rooted graphs $G$ and $H$, 
     % with labelings $\lambda_H$ and $\lambda_G$ respectively,  
     runs in time $f(|H|)\cdot \bigoh(|G|^{3})$ for some 
	 computable function $f$ and decides whether $H$ is a topological minor of $
     G$.\end{proposition}
