If $G$ is connected, then the forest embedding of $G$ consists of a single tree, i.e., it is a tree embedding. 

 \begin{longproposition}[\cite{sparsity}]\label{proptreedepth}
If a graph $G$ has no path of length at least ${\ell}$, then it has treedepth at most~$\ell$. 
 \end{longproposition}


\begin{longobservation}
    \label{separatorsInTreedepth}
    Let $G$ be a graph with a forest embedding $(F,f)$ and consider some vertex $v$. If the number of children of $v$ in $F$ is at least $\alpha$ and $Z$ denotes the set of vertices appearing in the root-to-$v$ path in the tree of $F$ containing $v$, then the number of connected components of  $G-Z$ is at least $\alpha$. 
\end{longobservation}
\begin{proof}
By the definition of forest embeddings,  (i) every descendant of $v$ in $F$ is adjacent in $G$ to either another descendant of $v$ in $F$ or a vertex in $Z$ and (ii) descendants of distinct children of $v$ in $F$ are non-adjacent in $G$. 
\end{proof} \fi




