%     Lemma \ref{lem:mainTreedepth} can be make constructive and implies an FPT algorithm for \cmpl{} parameterized by $\td$ and number of robots. We later prove that \cmpl{} is FPT parameterized by the number of robots alone. 
% \todo{Is the problem FPT by treedepth alone? If yes, is it easy to see?}
% \end{remark}

Since Lemma \ref{lem:mainTreedepth} achieves our objective of bounding the size of the optimal schedule when the graph has bounded treedepth, we next focus on the case where Lemma \ref{lem:nearHaven} is only able to guarantee that for every vertex $v$, there is a $q$-haven for $v$ anchored at some vertex $w$, where $q=\Theta(k^{2})$.



For a set $S \subseteq \R$ of robots and a subgraph $H$, a \emph{configuration} of $S$ w.r.t.~$H$ is an injection $\iota: \  S \longrightarrow V(H)$. We show using a lemma of Deligkas et al. (Lemma 10, \cite{DeligkasEGK024}, see arXiv version~\cite{DeligkasEGK024Arxiv} for the proof) that we can move the robots in a $\Theta(k^{2})$-haven from any configuration to any other configuration within the same haven, using a total of $\Oh(k^6)$ moves. 

\begin{longlemma}[Slightly modified statement of Lemma 10, \cite{DeligkasEGK024}]\label{lem:oldLemSwap}
Consider a vertex $w$ and three connected subgraphs $C_1, C_2, C_3$ of $G$ such that: (i) the pairwise intersection of the vertex sets of any pair of these subgraphs is exactly $w$, and (ii) $|V(C_1)| \geq k+1$, $|V(C_2)| \geq k+1$, and $|V(C_3)| \geq 2$. Let $H$ denote the subgraph  of $G$ induced by the vertices in $\{x\} \cup V(C_1) \cup V(C_2)$ whose distance from $w$ in $H$  is at most $p$. Then for any set of robots $S \subseteq \R$ in $H$ with current configuration $\iota(S)$, any configuration $\iota'(S)$ with respect to $H$ can be obtained from $\iota(S)$ via a sequence of $\Oh(k^{2}\cdot p)$ moves that take place in $H$.
\end{longlemma}

\begin{remark*}
Note that in Lemma \ref{lem:oldLemSwap} as stated in \cite{DeligkasEGK024}, each move is along a single edge. However, in this paper we allow moves along unobstructed paths, so the number of moves given by their lemma is an upper bound for us as well. Moreover, upon examining their statement and proof, we find that the value of $p$ used in \cite{DeligkasEGK024} was $k$ and hence the lemma simply gave an upper bound of $\bigoh(k^{3})$ on the number of moves, but we will set $p$ to be a value that is quadratic in $k$, hence we have restated the lemma to account for this. 
\end{remark*}





\begin{longlemma}\label{lem:implicationHaven}
Let $H_w$ be a strong $q$-haven anchored at some vertex $w$, where $q=\Theta(k^{2})$. 
Then, there exist three connected subgraphs $C_1, C_2, C_3$ of $G$ such that: (i) the pairwise intersection of the vertex sets of any pair of these subgraphs is exactly $w$, and (ii) $|V(C_1)| \geq k+1$, $|V(C_2)| \geq k+1$, and $|V(C_3)| \geq 2$, and (iii) $\bigcup_{i\in [3]} V(C_i) =V(H_w)$ and (iv) every vertex has distance $\bigoh(q)$ from $w$ in the graph induced by $\bigcup_{i\in [3]} E(C_i)$.
\end{longlemma}

\begin{proof}
   Say that $H_w$ is an $x$-$y$ path. Since $H_w$ is a strong $q$-haven anchored at $w$, it must be the case that     $w$ has distance $\bigoh(q)$ to both $x$ and $y$. 
   Let $x'$ and $y'$ denote the neighbors of $w$ on $H_w$, with $x'$ chosen as the one that is closer to $x$. 

   Since $w$ has degree at least three, there is a neighbor $u$ of $w$ that is distinct from $x'$ and $y'$. If $u$ is not in $H_w$, then we are done by choosing $C_1$ and $C_2$ to be the two subpaths from $w$ to the two endpoints of $H_w$ and choosing $C_3$ to be the graph comprising the edge $(u,w)$. 
   Otherwise, $u$ lies on $H_w$. Assume without loss of generality that $u$ lies between $w$ and $y$. Then, $u$ also lies between $y'$ and $y$. Then, set $C_1$ to be the subpath  $H_w[w,x]$. Set $C_3$ to be the graph comprising the edge $(w,y')$ and set $C_2$ to be the graph $H_w[w,y]+(w,u)-y'$.  

   This completes the proof of the lemma.
\end{proof} 


For a strong $q$-haven $H_w$ anchored at some vertex $w$, we denote by $\hat H_w$, the graph obtained by taking the union of $H_w$ and an arbitrarily chosen set of three edges incident on $w$. 

\begin{longlemma}
\label{lem:swap}
Let $H_w$ be a strong $q$-haven anchored at some vertex $w$, where $q=\Theta(k^{2})$. 
For any set of robots $S \subseteq \R$ in $H_w$ with current configuration $\iota(S)$, any configuration $\iota'(S)$ with respect to $H_w$ can be obtained from $\iota(S)$ via a sequence of $\Oh(k^6)$ moves that take place in $\hat H_w$.
\end{longlemma}


\begin{proof}
We invoke Lemma \ref{lem:implicationHaven} followed by Lemma \ref{lem:oldLemSwap} with $p=q$. Notice that $\hat H_w$ contains the required neighbor $u$ of $w$ in the proof of Lemma \ref{lem:oldLemSwap}. Hence, the moves take place in $\hat H_w$. 
\end{proof}













A connected subgraph $G'$ is called an  $(r,q)$-{\em meta-haven} if it is obtained by taking the union of the edges of $\{\hat H_{w_i}\mid i\in [r]\}$, where each $H_{w_i}$ is a strong $q$-haven anchored at $w_i$. A straightforward consequence of Lemma \ref{lem:swap} is the following. 


\begin{longlemma}
    \label{lem:metaSwap}
 Let $G'$ be an $(r,q)$-meta-haven, where $r\leq 2k$ and $q=\Theta(k^{2})$. 
For any set of robots $S \subseteq \R$ in $G'$ with current configuration $\iota(S)$, any configuration $\iota'(S)$ with respect to $G'$ can be obtained from $\iota(S)$ via a sequence of $\Oh(k^7)$ moves that take place in $G'$.
\end{longlemma}

We are now ready to complete the proof of the main lemma of this subsection. Let us restate it here. 

\stepbound*


\begin{proof}
If $G$ has treedepth bounded by $\bigoh(k^{2})$, then invoking  Lemma \ref{lem:mainTreedepth} with this bound on the treedepth, we conclude that if $I$ is a \YES-instance, then it has a schedule with  $2^{\bigoh(k^{4})}$ moves. 

Otherwise, Lemma \ref{lem:nearHaven} guarantees that for every vertex $v$, there is a $q$-haven for $v$ anchored at some vertex $w$,  where $q=\Theta(k^{2})$. Moreover, $H_w$ is a strong $q$-haven and has $v$ as one of its endpoints.
The proof idea from here onwards is similar to that of Eiben et al. (Theorem 15, \cite{DeligkasEGK024}). However, we have defined our notion of havens in such a way that our arguments are simpler. Assume without loss of generality that $R_1$ is a robot with a destination. Let us now describe a sequence of $\bigoh(k^{8})$ moves that take $R_1$ from $s_1$ to $t_1$. The complete schedule then repeats the same strategy for subsequent robots, giving us a bound of $\bigoh(k^{9})$ moves in total.

For every terminal $v$, fix $H_{w_v}$ to be a strong $q$-haven that has $v$ as one of its endpoints. 
Let $Z_1,\dots,Z_p$ denote meta-havens defined by $\hat H_{w_v}$, where $v$ is a terminal. By ensuring that each $Z_i$ is inclusion-wise maximal, we guarantee that $Z_i$ and $Z_j$ are disjoint for $i\neq j$. 

Let $P$ denote a walk from $s_1$ to $t_1$ in $G$. In the traversal of $P$ from $s_1$ to $t_1$, let $u_1$ and $u_2$ denote the first and last vertices, respectively, that belong to some meta-haven, say $Z_1$. Then, we replace the subwalk from $u_1$ to $u_2$ with a walk given by Lemma \ref{lem:metaSwap}, which takes $\bigoh(k^{7})$ moves. The other robots currently in the meta-heaven can be moved arbitrarily to other positions inside it. So, the only requirement of the configuration with which we invoke Lemma \ref{lem:metaSwap} is that $R_1$ starts in $u_1$ and ends in $u_2$. By doing this once for every meta-haven, we obtain a route for $R_1$ that enters and exits each meta-haven at most once and takes $\bigoh(k^{7})$ moves inside each meta-haven. Hence, we obtain a route for $R_1$ that takes $\bigoh(k^{8})$ moves overall. 
\end{proof}


\fi
\subsection{Succinct Representation of a Solution}

In what follows, fix an optimal schedule $\SSS=\{W_i\mid i\in [k]\}$ for an instance $I=(G, \R=(\M,\F), k, \ell)$. By Lemma \ref{lem:stepbound}, 
we may assume, without loss of generality, that $\SSS$ has length $2^{\bigoh(k^{4})}$.  
We also assume that no robot moves in two consecutive time steps since otherwise, the movements of such a robot  could be done in a single time step while the remaining robots wait. 
Moreover, we say that an edge $e$ of $G$ is {\em traversed by} $\SSS$ if there is an $i\in [k]$ and a time step $j$ such that the path $P^{i}_j$ contains the edge $e$. That is, some robot $R_i$ uses the edge $e$ in some time step $j$.  We denote by $G_\SSS$, the subgraph of $G$ induced by the edges traversed by $\SSS$. For a time step $j$, we denote by $G_{S,j}$ the subgraph of $G_\SSS$ induced by the edges traversed by $\SSS$ up to time step $j$.
%
A vertex $v$ in $G_\SSS$ is a \emph{waiting vertex} within time interval $[0,j]$ if there is a robot $R_i$ and a time step $j'\leq j$
% \todo{I: I think we should avoid using $t$ throughout this section (in the long version too). RMS: I've changed all occurrences.} 
such that $R_i$ is at $v$ at time steps $j'-1$ and $j$. We say that $v$ is a waiting vertex if it is a waiting vertex within some time interval. 
A vertex $v$ in $G_\SSS$ is an \emph{intersection} vertex within time interval  $[0,j]$ if its degree in $G_{S,j}$ is at least three. We say that $v$ is an intersection vertex if it is an intersection vertex within some time interval. 
A vertex $v$ in $G_{S,j}$ is an \emph{important} vertex within time interval $[0,j]$ if it is either a terminal vertex, or within time interval $[0,j]$ it is a waiting vertex or an intersection vertex. Otherwise, $v$ is \emph{unimportant} within time interval $[0,j]$.
We say that $v$ is an important (unimportant) vertex if it is important (resp.\ unimportant) within some time interval. 



\begin{observation}

\label{boundWaitingbyTime}
 The number of waiting vertices within time interval $[0,j]$ is at most $k+j$.
\end{observation}


\iflong \begin{proof}
Initially, the robots are on $k$ terminals and in every time step, exactly one robot moves to a (potentially new) waiting vertex while the remaining robots remain stationary.
\end{proof} \fi

\begin{observation}

\label{disjointPaths}
The unimportant vertices within any time interval $[0,j]$ induce a disjoint union of paths and any endpoint of any of these paths has degree 2 in $G_{S,j}$.
\end{observation}

\iflong \begin{proof}
Every vertex of degree at least three in $G_{S,j}$ is important within this time interval.
\end{proof} \fi

\newcommand{\Pcal}{\mathcal P}

For a time step $j$, we denote by $\Pcal_{S,j}$, the set of all $x$-$y$ paths $P$ of non-zero length such that $x$ and $y$ are distinct important vertices within time interval $[0,j]$ and every internal vertex of $P$ is an unimportant vertex within time interval $[0,j]$.

For two paths $P$ and $P'$ in $G$, their {\em crossing points} are those vertices that have degree at least three in the graph induced by the edges in $E(P)\cup E(P')$. 

We say that $\SSS$ is a {\em special schedule up to time step $j$} if, for every robot $R_i$ and $j>0$ such that $R_i$ moves in time step $j$, the path $P^i_j$ has at most four crossing points with any path in $\Pcal_{S,j'}$ where $j'\leq j-1$. 
% Essentially, the path that $R_i$ takes when it moves in time step $j$ has at most four crossing points with any path that has been taken by any robot in any time step prior to time step $j$ and which is never blocked by a waiting vertex at any point up to time step $j-1$.\todo{I: This last sentence is long and confusing. Can it be rephrased/broken? RMS: I removed this. The formal description is already clear, I think.}
Note that every schedule is trivially special at time step 1 since only a single path has been taken at this point.  Moreover, $\Pcal_{S,1}$ has size at least one because a move has been made and so, $\Pcal_{S,j}$ has size at least one for every $j$. 
We say that $\SSS$ is a {\em special schedule} if it is a special schedule up to the final time step. 

We say that two schedules are {\em equivalent at time step} $j$ if the positions of all the robots at the end of time $j$ is the same in both schedules, that is, robot $R_i$ is on vertex $v$ after time step $j$ in one schedule if and only if the same happens in the other schedule.
We say that two schedules are equivalent if they are equivalent at every time step. In particular, two equivalent schedules take the same number of time steps.

%Iyad asked about whether we can provide an explanation for the proof of these, but for now we don't seem to have space and nobody felt like pushing for it.


\begin{lemma}

\label{lem:isSpecial}
	There is a solution $\SSS'$ that is a special schedule.
\end{lemma}



\iflong \begin{proof}
We start with the schedule $\SSS$ and suppose that it has $h$ time steps. Let $\SSS'$ be a schedule that is equivalent to $\SSS$ and let $j'$ be the maximum time step such that $\SSS'$ is a special schedule up to time step $j'$. We choose $\SSS'$ so that $j'$ is maximized. As observed above, $j'\geq 1$. Since we are done otherwise, we assume that $j'\neq h$. Now, let $j=j'+1$. 

 Suppose that $R_i$ moves in time step $j$ using the path $P^i_j$. By our choice of $j'$ (and by extension, $j$) it must be the case that some path
 $P$ in $\Pcal_{S',j-1}$
 and $P^i_j$ have more than four crossing points. Along the traversal of $P^i_j$ from $u^i_{j-1}$ to $u^i_j$, let the second and third crossing points be $x_1$ and $x_2$, respectively. Then, we can replace the subpath $P^i_j[x_1,x_2]$ with the subpath $P[x_1,x_2]$ to obtain an alternate schedule that is equivalent to $\SSS$ and with fewer crossing points.
 In fact, by doing the same for every path $P$ in $\Pcal_{S',j-1}$ that has more than two crossing points with $P^i_j$, we obtain a schedule $\SSS''$ that is equivalent to $\SSS$ and which is also special up to time step $j=j'+1$, a contradiction to our choice of $\SSS'$. This completes the proof of the lemma.
\end{proof} \fi



Henceforth, we assume that the solution $\SSS$ is a special schedule. 


\begin{lemma}

\label{lem:boundImportant}
    The number of important vertices in $G_{\SSS}$ is bounded by $2^{\macrofk}$. 
\end{lemma}


\iflong \begin{proof}
Let $W$ denote the set of waiting vertices in $G_\SSS$ and let $I$ denote the set of intersection vertices in $G_\SSS$ that are not terminals or waiting vertices. Note that all but at most two of the terminals are by definition, waiting vertices. So, the number of important vertices is bounded by $|I|+|W|+2$. 


By Observation \ref{boundWaitingbyTime},  since the total number of moves in $\SSS$ is at most $\macrofk$ (which also bounds the number of time steps in $\SSS$), the number of waiting vertices in $G_\SSS$ is at most $k+\macrofk$. 
 Therefore, it suffices to bound the size of $I$. Let $I[j]$ denote the subset of $I$ that is important within time interval $[0,j]$. 
 Clearly, $|I|\leq |\bigcup_{j\leq t }I[j]\setminus I[j-1]|$.
    Notice that every vertex in $I[j]\setminus I[j-1]$ is either a crossing point of the path $P^i_j$ with some path in $\Pcal_{S,j-1}$ or the endpoint of $P^i_j$ that is distinct from $u^{i}_{j-1}$.
    By Lemma \ref{lem:isSpecial}, we have that $P^i_j$ has at most four crossing points with any path in $\Pcal_{S,j-1}$. Hence, we have that $|I[j]\setminus I[j-1]|$ is at most $4\cdot |\Pcal_{S,j}|+1$. Moreover, since each path in $\Pcal_{S,j-1}$ gets split into at most five parts by the crossing points, we have that $|\Pcal_{S,j}|\leq 5\cdot |\Pcal_{S,j-1}|+1$. For simplicity, let us bound $5\cdot |\Pcal_{S,j-1}|+1$ by $6 \cdot |\Pcal_{S,j-1}|$ since $\Pcal_{S,j-1}$ is always non-empty. This implies that $|\Pcal_{S,j}|\leq 6^j$ and hence, $|I[j]\setminus I[j-1]|$ is at most $4\cdot (6^{j}+1)$. This gives us the required bound of $\bigoh(\macrofk\cdot 6^{\macrofk})=2^{\macrofk}$ on the size of $I$ and since $|W|\leq k+\macrofk$, completes the proof of the lemma.
\end{proof} \fi





\subsection{Leveraging Succinct Representations and Topological Minor Containment}

In what follows, fix a schedule $\SSS=\{W_i\mid i\in [k]\}$ for an instance $I=(G, \R=(\M,\F), k, \ell)$. 

We define the \emph{representation} of $\SSS$ to be the rooted graph (denoted by $H_\SSS$) whose vertices are the important vertices of $G_\SSS$, and in which there is an edge between two vertices $u$ and $v$ if and only if there is a $u$-$v$ path in $G_\SSS$ whose internal vertices have degree 2 in $G_\SSS$ and are unimportant. Moreover, the terminals receive unique labels (assume that the terminals are labeled with $[p]$ for some $p\leq 2k$) and the remaining vertices receive the same label which is distinct from those of the terminals, say $p+1$. An illustration is provided in Figure~\ref{fig:representation}.
From Lemma~\ref{lem:boundImportant}, we directly obtain: 

\begin{lemma}
\label{lem:representationbound}
If a solution exists, then there is a solution whose representation has $2^{\macrofk}$ vertices.
\end{lemma}

