\subsection{Singular Value Decomposition}
\label{subsec:svd}
Let 
%\trung{besser: N x T} 
$\matr{Y} \in \mathbb{R}^{\mathrm{N} \times \mathrm{T}}$, then there exist the orthogonal matrices $\matr{U} = \left( \vect{u}_1, ..., \vect{u}_\mathrm{N} \right) \in \mathbb{R}^{\mathrm{N} \times \mathrm{N}}$ and $\matr{V} = \left( \vect{v}_1, ..., \vect{v}_\mathrm{T} \right) \in \mathbb{R}^{\mathrm{T} \times \mathrm{T}}$ and a rectangular diagonal matrix $\matr{S} = \mathrm{diag}(s_\mathrm{i}) \in \mathbb{R}^{\mathrm{N} \times \mathrm{T}}$ such that
\begin{align}
    \matr{Y} = \matr{U} \matr{S} \matr{V}^T = \sum_{i=1}^d s_i \vect{u}_i \vect{v}_i^{T} \label{equ:general_svd}
\end{align}
with unique singular values $s_1 \geq ... \geq s_\mathrm{d} \geq 0$, singular vectors $\vect{u}_\mathrm{i}, \vect{v}_\mathrm{j}$ and $d = \mathrm{min}(\mathrm{N}, \mathrm{T})$.
%
Note that the theoretical equality $\matr{Y} = \matr{U} \matr{S} \matr{V}^T$  only holds in the absence of numerical errors.
%, which is not feasible for practical applications with large matrices.
%Based on the preceding, two remarks of particular emphasis follow, which relate to the matrix $\matr{Y}$'s norm
The latter motivates the introduction of two norms which will be utilized below  to adapt the SVD, viz.
\begin{align}
    ||\matr{Y}||_2 = s_1
    \qquad \qquad
    \mathrm{and}
    \qquad \qquad
    ||\matr{Y}||_\mathrm{F} = \sqrt{\sum_{i=1}^\mathrm{N} \sum_{i=1}^\mathrm{T} |y_\mathrm{ij}|^2} = \sqrt{\sum_{i=1}^d s_\mathrm{i}^2} \label{equ:norms} \, .
\end{align}
In Eqn. (\ref{equ:norms})  $||\cdot||_2$ and $||\cdot||_\mathrm{F}$ refer to the L2 and Frobenius norm, respectively. Additionally, we define $r = \mathrm{max}(k \in \mathbb{N}: s_\mathrm{k} \neq 0)$ as the amount of non-zero singular values which is equivalent to  $\mathrm{rank}(\matr{Y}) = r$. Hence, only the first $r$ singular vectors are required to determine the matrix $\matr{Y}$ from Eqn. (\ref{equ:general_svd})
%via the SVD, 
This allows for the definition of a reduced SVD (rSVD), i.e., let $\mathrm{rank}(\matr{Y}) = r \leq \mathrm{min}(\mathrm{N},\mathrm{T})$ such that
\begin{align}
    \matr{Y} = \matr{U}_\mathrm{r} \matr{S}_\mathrm{r} \matr{V}_\mathrm{r}^\mathrm{T} = \sum_{i=1}^\mathrm{r} s_\mathrm{i} \vect{u}_\mathrm{i} \vect{v}_\mathrm{i}^\mathrm{T} \label{equ:reduced_svd}
\end{align}
where the rSVD matrices read $\matr{U}_\mathrm{r} = \left( \vect{u}_1, ..., \vect{u}_\mathrm{r} \right) \in \mathbb{R}^{\mathrm{N} \times \mathrm{r}}$ and $\matr{V}_\mathrm{r} = \left( \vect{v}_1, ..., \vect{v}_\mathrm{r} \right) \in \mathbb{R}^{\mathrm{T} \times \mathrm{r}}$ as well as $\matr{S}_\mathrm{r} = \mathrm{diag}(s_\mathrm{1}, ..., s_\mathrm{r}) \in \mathbb{R}^{\mathrm{r} \times \mathrm{r}}$. 
%
Instead of $\matr{Y}$, the matrices $\matr{U}_\mathrm{r}$ and $\matr{V}_\mathrm{r}$ and the vector of diagonal $\matr{S}$-entries $\vect{s} \in \mathbb{R}^\mathrm{r}$ have to be stored. In practice, this results in a storage overhead when the matrix $\matr{Y}$ is of high rank, although a steep decay in singular values is observed. 
%\nkuehl{Check if a SVD can be used for data compression}
%
Consequently, further reduction of the efforts are sought. 

Due to its broad applicability and versatility, 
%in linear and non-linear flow problems (\cite{lassila2014model}), 
a POD-based model-order reduction is often pursued. The approach aims at a low-rank approximation while also preserving the overall solution behavior by
%Concerning the reduced SVD, this yields the approach of additionally 
truncating the smallest non-zero singular values up to a specific truncation criterion. In line with the assumption of a fast decay in Kolmogorov N-width (\cite{kolmogoroff1936uber, benner2020model}), 
%which is expressed as 
the POD modes corresponding to small singular values are deemed to have an insignificant impact on the approximation quality, which leads to the  truncated SVD (tSVD). The rank-$q$ tSVD approximation of $\matr{Y}$ with $1 \leq q < r$ is defined as
\begin{align}
    \matr{Y}_\mathrm{q} = \matr{U}_\mathrm{q} \matr{S}_\mathrm{q} \matr{V}_\mathrm{q}^\mathrm{T} = \sum_\mathrm{i=1}^\mathrm{q} s_\mathrm{i} \vect{u}_\mathrm{i} \vect{v}_\mathrm{i}^\mathrm{T} \label{equ:truncated_svd}
     \; . 
\end{align}
 The tSVD matrices read $\matr{U}_\mathrm{q} = \left( \vect{u}_1, ..., \vect{u}_\mathrm{q} \right) \in \mathbb{R}^{\mathrm{N} \times \mathrm{q}}$, $\matr{V}_\mathrm{q} = \left( \vect{v}_1, ..., \vect{v}_\mathrm{q} \right) \in \mathbb{R}^{\mathrm{T} \times \mathrm{q}}$ and $\matr{S}_\mathrm{q} = \mathrm{diag}(s_1, ..., s_\mathrm{q}) \in \mathbb{R}^{\mathrm{q} \times \mathrm{q}}$. $\matr{Y}_\mathrm{q} \in \mathbb{R}^{\mathrm{N} \times \mathrm{T}}$ denotes the matrix obtained 
