            \matr{0} & \matr{I}
    \end{bmatrix} \matr{V}^\prime(:,1:q) \label{equ:update_V_column} \\
    \tilde{\matr{S}}_\mathrm{q} &= \matr{S}^\prime(1:q,1:q) \label{equ:update_S_column} \\
    \tilde{\matr{U}}_\mathrm{q} &= 
    \begin{bmatrix}
            \matr{U} & \matr{Q}_\mathrm{B}
    \end{bmatrix} \matr{U}^\prime(:,1:q) \label{equ:update_U_column} \, ,
\end{align}
where $\matr{U}^\prime \matr{S}^\prime {\matr{V}^\prime}^\mathrm{T}$ denotes the rSVD of $\matr{K}$ with
\begin{align}
    \matr{K} = 
