            \matr{S} & \matr{U}^\mathrm{T} \matr{B} \\ \matr{0} & \matr{R}_\mathrm{B}
    \end{bmatrix}
    %= \matr{U}^\prime \matr{S}^\prime {\matr{V}^\prime}^\mathrm{T} 
    \label{equ:matrix_K_column} \, .
\end{align}
