\section{Basic Definitions}\label{se:preliminaries}

Let $V(G)$ and $E(G)$ denote the set of vertices and the set of edges of a graph~$G$, respectively. Also, for a vertex $v \in V(G)$, 
%$E(v)$ the set of edges incident to $v$, and by
let $N(v)$ be the set of \emph{neighbors of $v$}, i.e., the set of vertices adjacent to~$v$. The value $|N(v)|$ is the \emph{degree of $v$}, and is denoted by $\deg_G(v)$. For a positive integer $k$, a graph $G$ is a \emph{$k$-graph} if $\deg_G(v) \leq k$ for each $v \in V(G)$.  
If $\deg_G(v)=2$ and $N(v) = \{u,w\}$, \emph{smoothing} $v$ consists of removing $v$ (and its incident edges) from $G$ and adding the edge $(u,w)$ in $G$ (i.e., smoothing a vertex is the reverse of subdividing an edge).
%

\medskip
\noindent \textbf{Rectilinear Drawings.} 
A \emph{rectilinear drawing} $\Gamma$ of a graph $G$ is a drawing such that: $(i)$ each vertex $v \in V(G)$ is mapped to a distinct point $p_v$ of an integer grid; $(ii)$ each edge $e=(u,v) \in E(G)$ is mapped to either a horizontal or a vertical segment $s_e$ connecting~$p_u$ and~$p_v$; $(iii)$ if $v \in V(G)$ and $e \in E(G)$, $s_e$ does not intersect $p_v$ unless $v$ is an end-vertex of $e$. We can assume $G$ to be a 4-graph, as otherwise it does not have a rectilinear drawing. We will denote by $x(v)$ and $y(v)$ the $x$- and $y$-coordinates of $p_v$.

%
A \emph{vertex of $\Gamma$} is either a point that corresponds to a vertex of~$G$, in which case it is called a \emph{real-vertex}, or it is a point where two edges of~$G$ cross, in which case it is called a \emph{crossing-vertex}. 
%Clearly, if $c$ is a crossing-vertex of $\Gamma$ then $\deg_\Gamma(c) = 4$. 
If $\Gamma$ has no crossing-vertices, it is a \emph{planar rectilinear drawing}. An \emph{edge of $\Gamma$} is a portion of an edge of $G$ delimited by two vertices of $\Gamma$, which does not contain other vertices of $\Gamma$ in its interior. An edge of $\Gamma$ coincides with an edge $e$ of $G$ when $e$ does not cross any other edges of $G$ in $\Gamma$. 
%
Drawing $\Gamma$ divides the plane into connected regions, called \emph{faces}. The \emph{boundary} of each face $f$ is the circular sequence of vertices (either real- or crossing-vertices) and edges of $\Gamma$ that delimit $f$. The unique infinite region is the \emph{external face} of $\Gamma$; the other faces are the \emph{internal faces} of $\Gamma$. 
%We denote by $V(\Gamma)$, $E(\Gamma)$, and $F(\Gamma)$ the set of vertices, edges, and faces of $\Gamma$. 
For a face $f$ of $\Gamma$, we denote by ${\cal B}(f)$ the boundary of $f$. If $f$ is the external face of $\Gamma$, we call ${\cal B}(f)$ the \emph{external cycle of} $\Gamma$.
%
%\todo[inline]{Missing: unit edge-length definition, external face drawn as a rectangle specification, necessary condition: graph is biconnected.}

\medskip
\noindent \textbf{Rotation systems.} A \emph{rotation system ${\cal R}(G)$ of $G$} specifies the clockwise order of edges in $E(v)$, for each vertex $v \in V(G)$. ${\cal R}(v)$ denotes the restriction of ${\cal R}(G)$ to $v$. A (rectilinear) drawing $\Gamma$ of $G$ determines a rotation system for $G$; in addition, $\Gamma$ determines the clockwise order of the edges incident to each crossing-vertex. For a given rotation system ${\cal R}(G)$, we say that $\Gamma$ \emph{preserves} ${\cal R}(G)$ if the rotation system determined by $\Gamma$ coincides with ${\cal R}(G)$. 

\medskip
\noindent \textbf{Our models.} We study \emph{\UERlong} (\emph{\UER drawings}), i.e., rectilinear drawings where all edges have unit length and all faces (including the external one) are rectangles.
Note that, in a \UER drawing, the external cycle only contains real-vertices.
Within the \UER model we also define a more restricted model, \emph{\UERIIlong} (\emph{\UERII drawings}), where each face is a square of unit side; see \Cref{fig:crd-examples}. The next simple~property~holds.
%
%
%\begin{itemize}
%\item \emph{\UERIlong (\UERI drawings)}. In this model, at least one of the two sides of each face has unit length.
%\end{itemize}

%If the boundary ${\cal B}(f)$ of a face $f \in F(\Gamma)$ has a rectangular shape in $\Gamma$, we say that $f$ is an \emph{R-face}. 
%If ${\cal B}(f)$ contains exactly one vertex with a reflex angle (i.e., an angle of 270$^\circ$) inside $f$, we say that $f$ is an \emph{L-face}.
%
% We focus the attention on the following types of rectilinear drawings:

% \begin{itemize}
% \item \emph{Unit Edge-length Rectilinear drawing} (\emph{UER drawing}): each edge of the drawing has unit length. 

% \item \emph{Unit Face-area Rectilinear drawing} (\emph{UFR drawing}): each internal face of the drawing has unit area.
% \end{itemize}

%Clearly, any UFR drawing is also a UER drawing, but the reverse is not true in general.

%We formalize a simple observation about the external boundary of any \UER, and thus of any \UERII, drawing.


\begin{property}\label{pr:external-face}
Let $\Gamma$ be a \UER drawing of a graph $G$, let $C$ be the external cycle of $\Gamma$, and let $c_1, c_2, c_3, c_4$ be the vertices of $C$ at the corners of $\Gamma$. Then: $(i)$ $c_1, c_2, c_3, c_4$ have degree 2 in $G$; $(ii)$ each other vertex of $C$ has degree at most 3 in $G$; $(iii)$ the path in $C$ between two consecutive corners has the same length as the path in $C$ between the other two corners.  
%\begin{enumerate}
% \item Each of $c_1, c_2, c_3, c_4$ has degree 2 in $G$.
% \item Each of the other vertices of $C$ has degree at most 3 in $G$.
% \end{enumerate}
\end{property}


%\subparagraph{Remark.}
We will assume that the input graph $G$ is biconnected and it is not a cycle, as
biconnectivity is necessary for the existence of \UER drawings, and if $G$ is a cycle the test is trivial: an \UERII drawing exists iff $G$ is a $4$-cycle; an \UER drawing exists iff $G$ has even length. 
%it is easy to test in $O(n)$ time if $G$ admits a specific drawing. In the \UERII setting $G$ must have length exactly four, while in the \UER setting it must have an even length to be represented as a unit edge-length grid rectangle.


